// AFE Charge demo data and state. No network APIs, payment rails or charger control.
const DEMO_DATA = {
  stations: [
    {id:'afe-rivonia',name:'382 Rivonia--AFE Charge',area:'Edenburg, Sandton',address:'382 Rivonia Rd, Edenburg, Sandton, 2196 South Africa',distance:0.1,lat:-26.043889,lng:28.060290,open:'Open 24 hours',available:1,rate:5.50,successRate:99,lastSuccess:'Recently startable · demo',cable:false,parking:'Use the marked AFE Charge bays. Confirm the charger indicator is green before connecting.',resilience:'Solar + Storage',economics:{demandShare:16800,breakEven:132,utilization:51,payback:29,model:'Self-owned'},connectors:[{id:'afe-rv-1',type:'CCS',label:'DC Fast · Gun 01',powerType:'DC',kw:120,status:'Available',cable:false},{id:'afe-rv-2',type:'CCS',label:'DC Fast · Gun 02',powerType:'DC',kw:120,status:'In use',cable:false},{id:'afe-rv-3',type:'CCS2',label:'DC Fast · Gun 03',powerType:'DC',kw:120,status:'Available',cable:false},{id:'afe-rv-4',type:'Type 2',label:'AC · Gun 04',powerType:'AC',kw:22,status:'Available',cable:true}]},
    {id:'oxford',name:'Oxford Road Hub',area:'Rosebank',address:'14 Oxford Road, Rosebank',distance:1.2,lat:-26.1430,lng:28.0367,open:'Open 24 hours',available:2,rate:6.50,successRate:98,lastSuccess:'Today, 09:18',cable:false,parking:'Open parking area. Keep your cable close and use the marked bays.',resilience:'Solar + Storage',economics:{demandShare:18600,breakEven:145,utilization:52,payback:32,model:'Host revenue share'},connectors:[{id:'ox-1',type:'CCS',label:'CCS2 · Plug 01',powerType:'DC',kw:150,status:'Available',cable:false},{id:'ox-2',type:'CCS',label:'CCS2 · Plug 02',powerType:'DC',kw:150,status:'Available',cable:false},{id:'ox-3',type:'Type 2',label:'Type 2 · Plug 03',powerType:'AC',kw:22,status:'In use',cable:true}]},
    {id:'rosebank',name:'Rosebank Mall',area:'Rosebank',address:'50 Bath Avenue, Rosebank',distance:2.4,lat:-26.1467,lng:28.0436,open:'06:00–22:00',available:3,rate:6.80,successRate:96,lastSuccess:'Today, 08:42',cable:true,parking:'Open mall parking. Cable theft can happen; stay near your vehicle.',resilience:'Smart scheduling',economics:{demandShare:12400,breakEven:118,utilization:73,payback:16,model:'Self-owned'},connectors:[{id:'rb-1',type:'CCS',label:'CCS2 · Bay A',powerType:'DC',kw:120,status:'Available',cable:false},{id:'rb-2',type:'CHAdeMO',label:'CHAdeMO · Bay B',powerType:'DC',kw:50,status:'Available',cable:false},{id:'rb-3',type:'Type 2',label:'Type 2 · Bay C',powerType:'AC',kw:22,status:'Available',cable:true}]},
    {id:'sandton',name:'Sandton Central',area:'Sandton',address:'1 Alice Lane, Sandton',distance:5.8,lat:-26.1076,lng:28.0567,open:'Open 24 hours',available:1,rate:7.10,successRate:91,lastSuccess:'Yesterday, 20:12',cable:false,parking:'Secure access-controlled garage. Follow attendant directions.',resilience:'Grid only',economics:{demandShare:21200,breakEven:166,utilization:38,payback:46,model:'Investor-funded'},connectors:[{id:'sc-1',type:'CCS',label:'CCS2 · Plug 04',powerType:'DC',kw:100,status:'Available',cable:false},{id:'sc-2',type:'Type 2',label:'Type 2 · Plug 05',powerType:'AC',kw:22,status:'Fault',cable:true}]}
  ],
  demoCard:{brand:'Visa',last4:'4821'},
  seedWallet:250,
  currency:'R',vatRate:.15
};
const STORE_KEY='afeChargeDemoV3';
DEMO_DATA.fleet={vehicleId:'AFE-FLT-03',plate:'CA 827 441',cycle:'01–30 November 2026',priorSessions:2,priorEnergy:84.6,priorAmount:548.90};
const appState={page:'find',homeView:'list',stationId:'afe-rivonia',connectorId:'afe-rv-1',mode:'amount',limit:100,payment:'card',customerType:'personal',failure:'none',filter:{connector:'Any',power:'Any',recent:false,sort:false},active:null,recordId:null,selectedMarker:null,mapsState:'idle',mapsInstance:null,mapMarkers:[],guestCode:'AFE-RV-01',guestLimit:200,toastTimer:null,tick:null};
function loadStore(){try{const v=JSON.parse(localStorage.getItem(STORE_KEY)||'{}');return{wallet:Number.isFinite(v.wallet)?v.wallet:DEMO_DATA.seedWallet,payment:v.payment||'card',history:Array.isArray(v.history)?v.history:[],notifications:Array.isArray(v.notifications)?v.notifications:[],vehicle:v.vehicle||null,cpoMode:!!v.cpoMode,loadShedding:!!v.loadShedding,homeView:v.homeView||'list',language:v.language||'en',theme:v.theme||'light',fontSize:v.fontSize||'medium',walletLedger:Array.isArray(v.walletLedger)?v.walletLedger:[],cardLast4:v.cardLast4||DEMO_DATA.demoCard.last4,feedback:Array.isArray(v.feedback)?v.feedback:[]}}catch{return{wallet:DEMO_DATA.seedWallet,payment:'card',history:[],notifications:[],vehicle:null,cpoMode:false,loadShedding:false,homeView:'list',language:'en',theme:'light',fontSize:'medium',walletLedger:[],cardLast4:DEMO_DATA.demoCard.last4,feedback:[]}}}
let store=loadStore();
function saveStore(){try{localStorage.setItem(STORE_KEY,JSON.stringify(store));return true}catch(error){console.warn('AFE Charge: local storage unavailable',error);return false}}
const I18N=window.AFE_I18N.core;
function t(key){return I18N[store.language]?.[key]||I18N.en[key]||key}
function mapsLanguage(){return{en:'en',af:'af',zu:'zu',zh:'zh-CN'}[store.language]||'en'}
function applyPreferences(){document.documentElement.dataset.theme=store.theme;document.documentElement.dataset.fontSize=store.fontSize;document.documentElement.lang=({en:'en',af:'af',zu:'zu',zh:'zh-CN'})[store.language]||'en';document.documentElement.style.colorScheme=store.theme==='dark'?'dark':'light';const meta=document.querySelector('meta[name=theme-color]');if(meta)meta.content=store.theme==='dark'?'#0d1511':'#f4f7f4'}
function money(n){return `${DEMO_DATA.currency} ${new Intl.NumberFormat('en-US',{minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(n||0))}`}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function station(id=appState.stationId){return DEMO_DATA.stations.find(s=>s.id===id)||DEMO_DATA.stations[0]}
function connector(s=station(),id=appState.connectorId){return s.connectors.find(c=>c.id===id)||s.connectors.find(c=>c.status==='Available')||s.connectors[0]}
function isStartable(s){return s.connectors.some(c=>c.status==='Available')&&!(store.loadShedding&&s.resilience==='Grid only')}
function availableCount(s){return isStartable(s)?s.available:0}
function resilienceBadge(s){return `<span class="app-badge resilience">${esc(s.resilience)}${store.loadShedding&&s.resilience==='Grid only'?' · unavailable':''}</span>`}
function economyMarkup(s,compact=false){const e=s.economics,ratio=Math.min(100,Math.round(e.utilization/e.breakEven*100));return `<div class="app-economy ${compact?'compact':''}"><div class="app-row"><span>Monthly demand cost share</span><b>${money(e.demandShare)}</b></div><div class="app-row"><span>Break-even · daily energy</span><b>${e.breakEven} kWh/day</b></div><div class="app-row"><span>Current utilisation</span><b>${e.utilization}%</b></div><div class="app-progress"><i style="width:${ratio}%"></i></div><div class="app-row"><span>Partnership · payback estimate</span><b>${esc(e.model)} · ${e.payback} mo</b></div></div>`}
function filteredStations(){return DEMO_DATA.stations.filter(s=>{
  if(appState.filter.recent&&!isStartable(s))return false;
  return s.connectors.some(c=>(c.status==='Available'||!appState.filter.recent) && (appState.filter.connector==='Any'||c.type===appState.filter.connector)&&(appState.filter.power==='Any'||c.powerType===appState.filter.power));
}).sort((a,b)=>store.cpoMode?(b.economics.utilization/b.economics.breakEven)-(a.economics.utilization/a.economics.breakEven)||a.economics.payback-b.economics.payback:appState.filter.sort?b.successRate-a.successRate:a.distance-b.distance)}
function recommendation(){return filteredStations().find(s=>isStartable(s))||null}
function toggleOpsMode(){store.cpoMode=!store.cpoMode;saveStore();renderHome()}
function toggleLoadShedding(){store.loadShedding=!store.loadShedding;saveStore();renderHome()}
function startScanDemo(){const s=recommendation();if(!s){toast('No startable demo station under these filters');return}appState.customerType='personal';appState.stationId=s.id;appState.connectorId=s.connectors.find(c=>c.status==='Available')?.id||s.connectors[0].id;appState.page='setup';render();toast(`Demo QR scanned · ${s.name}`)}
function appHeader(){const unread=store.notifications.filter(n=>!n.read).length;return `<header class="app-header"><div class="app-brand"><span class="app-brandmark">ϟ</span><span>AFE Charge</span></div><div class="app-inline"><span class="demo-chip">DEMO · NO REAL CHARGE</span><button class="app-button ghost mode-toggle" onclick="toggleOpsMode()">${store.cpoMode?'Driver view':'CPO view'}</button><button class="app-button ghost" aria-label="Notifications" onclick="showPage('notifications')">♧${unread?` <sup>${unread}</sup>`:''}</button></div></header>${!navigator.onLine?'<div class="app-notice" style="margin:8px 14px 0">Offline demo · station status may be out of date.</div>':''}`}
function nav(){const scanActive=['scan','guest','guestConnecting'].includes(appState.page);return `<nav class="app-nav"><button class="${appState.page==='find'?'active':''}" onclick="showPage('find')"><span class="nav-icon">⌂</span>${t('home')}</button><button class="nav-scan ${scanActive?'active':''}" aria-label="${t('scan')}" onclick="showPage('scan')"><span class="nav-icon">▦</span>${t('scan')}</button><button class="${appState.page==='history'||appState.page==='summary'||appState.page==='invoice'?'active':''}" onclick="showPage('history')"><span class="nav-icon">▤</span>${t('history')}</button><button class="${appState.page==='payments'||appState.page==='profile'||appState.page==='fleet'||appState.page==='settings'||appState.page==='cardForm'?'active':''}" onclick="showPage('profile')"><span class="nav-icon">◉</span>${t('me')}</button></nav>`}
function shell(content){applyPreferences();document.querySelector('.appview').innerHTML=`<div class="app-root">${appHeader()}<main class="app-main">${content}</main>${nav()}<div id="overlayRoot"></div><div id="toastRoot"></div></div>`}
function showPage(page){appState.page=page;render()}
function render(){if(appState.page==='find')return renderHome();if(appState.page==='station')return renderStation();if(appState.page==='setup')return renderSetup();if(appState.page==='failure')return renderFailure();if(appState.page==='live')return renderLive();if(appState.page==='summary')return renderSummary();if(appState.page==='history')return renderHistory();if(appState.page==='invoice')return renderInvoice();if(appState.page==='notifications')return renderNotifications();if(appState.page==='profile')return renderProfile();if(appState.page==='payments')return renderPayments();if(appState.page==='fleet')return renderFleetStatement();if(appState.page==='scan')return renderScan();if(appState.page==='guest')return renderGuest();if(appState.page==='guestConnecting')return renderGuestConnecting();if(appState.page==='wallet')return renderWallet();if(appState.page==='settings')return renderSettings();if(appState.page==='emergency')return renderEmergency();if(appState.page==='feedback')return renderFeedback();if(appState.page==='help')return renderHelp();if(appState.page==='cardForm')return renderCardForm();renderHome()}
function renderHome(){const list=filteredStations(),rec=recommendation(),ops=store.cpoMode;const stations=list.map(s=>`<article class="app-card app-station" onclick="openStation('${s.id}')"><div class="app-row"><div><h3>${esc(s.name)}</h3><div class="app-muted">${esc(s.area)} · ${s.distance.toFixed(1)} km · ${esc(s.open)}</div></div><span class="app-badge">${availableCount(s)} ${store.loadShedding&&s.resilience==='Grid only'?'offline':'free'}</span></div>${ops?`<div class="app-row" style="margin-top:8px">${resilienceBadge(s)}<span class="app-small">${esc(s.economics.model)}</span></div>${economyMarkup(s,true)}`:`<div class="app-inline" style="margin-top:10px"><span class="app-stat">Gun status<b>${availableCount(s)} available · ${s.connectors.filter(c=>c.status==='Fault').length} fault</b></span><span class="app-stat">24h start success<b>${s.successRate}% · ${esc(s.lastSuccess)}</b></span></div><div class="app-row" style="margin-top:9px"><b>${money(s.rate)} <span class="app-muted">/ kWh incl. VAT</span></b><span class="app-small">${s.connectors.map(c=>c.type).filter((x,i,a)=>a.indexOf(x)===i).join(' · ')}</span></div>`}</article>`).join('');const viewControls=!ops?`<div class="app-view-toggle"><button class="${store.homeView==='map'?'selected':''}" onclick="setHomeView('map')">⌖ ${t('map')}</button><button class="${store.homeView==='list'?'selected':''}" onclick="setHomeView('list')">☷ ${t('list')}</button></div>`:'';const retailMap=!ops&&store.homeView==='map'?renderMapView():'';shell(`<div class="app-row"><div><div class="app-small">SOUTH AFRICA · ZAR</div><h1>${ops?'CPO operations':t('stations')}</h1></div>${ops?`<button class="app-button secondary" onclick="toggleLoadShedding()">${store.loadShedding?'End':'Simulate'} load-shedding</button>`:`<button class="app-button secondary" onclick="openFilters()">☷ Filter</button>`}</div>${viewControls}<div class="app-notice" style="margin:10px 0">${ops?'Operator demo · economics and resilience are simulated estimates.':'Demo station data · no live charger connection'}</div>${ops?`<div class="app-card ops-intro"><b>Station economics</b><div class="app-muted">Ranked by current utilisation relative to daily break-even energy. Payback is a scenario estimate.</div></div>`:store.homeView==='map'?retailMap:`${rec?`<div class="app-card app-recommend"><div class="app-small" style="color:#cce0d2">MOST RELIABLE AVAILABLE</div><h2>${esc(rec.name)}</h2><div class="app-muted">${esc(rec.area)} · ${rec.distance.toFixed(1)} km · ${esc(rec.open)}</div><div class="app-inline" style="margin-top:12px"><span class="app-stat">Available guns<b>${availableCount(rec)} available</b></span><span class="app-stat">24h start success<b>${rec.successRate}% · ${esc(rec.lastSuccess)}</b></span></div><div class="app-row" style="margin-top:12px"><strong>${money(rec.rate)} <span class="app-muted">/ kWh incl. VAT</span></strong><button class="app-button" onclick="openStation('${rec.id}')">View station →</button></div></div>`:'<div class="app-card app-empty">No station matches these filters. Adjust filters to see more.</div>'}<button class="app-button full scan-demo" onclick="showPage('scan')">▦ ${t('scanTitle')} · ${t('scan')}</button><div class="app-row"><h2>${t('stations')}</h2><button class="app-button ghost" onclick="appState.filter.sort=!appState.filter.sort;renderHome()">${appState.filter.sort?'Sorted by starts':'Sort by start rate'}</button></div>`}${!ops&&store.homeView==='map'?'':stations||'<p class="app-muted">No matching stations.</p>'}`);if(!ops&&store.homeView==='map'){loadGoogleMaps();drawGoogleMap()}}
function setHomeView(view){store.homeView=view;appState.homeView=view;saveStore();renderHome()}
function renderMapView(){const s=appState.selectedMarker?station(appState.selectedMarker):null;return `<section class="app-map-wrap"><div id="afeMap" class="app-map-canvas">${!window.AFE_CONFIG?.GOOGLE_MAPS_API_KEY?`<div class="map-key-notice"><b>${t('keyMissing')}</b><p>${t('mapUnavailable')}</p><code>window.AFE_CONFIG.GOOGLE_MAPS_API_KEY</code></div>`:appState.mapsState==='error'?`<div class="map-key-notice"><b>Google Maps unavailable</b><p>Check the key, billing, enabled Maps JavaScript API and HTTP referrer restrictions.</p><button class="app-button secondary" onclick="retryGoogleMaps()">Retry</button></div>`:appState.mapsState!=='ready'?`<div class="map-loading">${t('location')} · ${appState.mapsState==='loading'?'Loading Google Maps…':''}</div>`:''}</div><div id="mapSheetRoot">${s?mapStationSheet(s):`<div class="app-card map-hint">${t('location')}<br><span class="app-muted">${t('mapHint')}</span></div>`}</div></section>`}
function mapStationSheet(s){return `<div class="app-card map-bottom-sheet"><div class="app-row"><div><h3>${esc(s.name)}</h3><div class="app-muted">${esc(s.area)} · ${s.distance.toFixed(1)} km</div></div><span class="app-badge">${availableCount(s)} available</span></div><div class="app-row" style="margin-top:10px"><b>${money(s.rate)} / kWh</b><button class="app-button" onclick="navigateToStation('${s.id}')">↗ ${t('directions')}</button></div></div>`}
function showMapStation(id){appState.selectedMarker=id;const root=document.getElementById('mapSheetRoot');if(root)root.innerHTML=mapStationSheet(station(id))}
function navigateToStation(id){const s=station(id);const destination=`${s.lat.toFixed(6)},${s.lng.toFixed(6)}`;const url=`https://www.google.com/maps/dir/?api=1&destination=${destination}`;window.open(url,'_blank','noopener,noreferrer')}
function failGoogleMaps(){clearTimeout(appState.mapsTimer);appState.mapsState='error';appState.mapsInstance=null;renderHome()}
function loadGoogleMaps(){const key=String(window.AFE_CONFIG?.GOOGLE_MAPS_API_KEY||'').trim();if(!key){appState.mapsState='missing';return}if(window.google?.maps?.importLibrary){appState.mapsState='ready';return}if(appState.mapsState==='loading')return;appState.mapsState='loading';window.gm_authFailure=failGoogleMaps;window.afeGoogleMapsReady=async()=>{try{await Promise.all([google.maps.importLibrary('maps'),google.maps.importLibrary('marker')]);clearTimeout(appState.mapsTimer);appState.mapsState='ready';renderHome()}catch{failGoogleMaps()}};const script=document.createElement('script'),params=new URLSearchParams({key,loading:'async',v:'weekly',callback:'afeGoogleMapsReady',libraries:'marker',language:mapsLanguage(),region:'ZA'});script.src=`https://maps.googleapis.com/maps/api/js?${params.toString()}`;script.async=true;script.onerror=failGoogleMaps;appState.mapsTimer=setTimeout(()=>{if(appState.mapsState==='loading')failGoogleMaps()},14000);document.head.appendChild(script)}
function retryGoogleMaps(){appState.mapsState='idle';loadGoogleMaps();renderHome()}
function drawGoogleMap(){const el=document.getElementById('afeMap');if(!el||appState.mapsState!=='ready'||!window.google?.maps)return;try{appState.mapMarkers.forEach(marker=>{marker.map=null});appState.mapMarkers=[];const {Map}=google.maps;appState.mapsInstance=new Map(el,{center:{lat:-26.043889,lng:28.060290},zoom:15,mapId:window.AFE_CONFIG?.GOOGLE_MAP_ID||'DEMO_MAP_ID',mapTypeControl:false,streetViewControl:false,fullscreenControl:false});const markers=google.maps.marker?.AdvancedMarkerElement;if(markers){addGoogleMarkers(markers);return}google.maps.importLibrary('marker').then(({AdvancedMarkerElement})=>addGoogleMarkers(AdvancedMarkerElement)).catch(failGoogleMaps)}catch{failGoogleMaps()}}
function addGoogleMarkers(AdvancedMarkerElement){if(!appState.mapsInstance)return;DEMO_DATA.stations.forEach(s=>{const markerContent=document.createElement('button');markerContent.type='button';const featured=s.id==='afe-rivonia';markerContent.className=`afe-map-marker ${featured?'featured afe-featured-site':''}`;markerContent.innerHTML=featured?`<span class="marker-bolt">ϟ</span><small>${availableCount(s)}</small>`:`<span>${availableCount(s)}</span>`;markerContent.setAttribute('aria-label',`${s.name}: ${availableCount(s)} ${t('available')||'available'}`);const marker=new AdvancedMarkerElement({map:appState.mapsInstance,position:{lat:s.lat,lng:s.lng},title:s.name,content:markerContent,gmpClickable:true});marker.addListener('gmp-click',()=>showMapStation(s.id));appState.mapMarkers.push(marker)})}
function renderScan(){shell(`<div class="app-card scan-panel"><div class="app-small">${t('guestMode')}</div><h1>${t('scanTitle')}</h1><p class="app-muted">No sign-in or camera permission is needed in this demo. Enter the charger ID from its label.</p><label class="app-label">${t('enterCharger')}</label><input class="app-input" id="guestCodeInput" value="${esc(appState.guestCode)}" autocomplete="off" autocapitalize="characters" placeholder="AFE-OX-01"><button class="app-button full" style="margin-top:10px" onclick="simulateGuestScan()">${t('simulateScan')}</button><div class="app-divider"></div><button class="app-button secondary full" onclick="showPage('help')">${t('help')}</button><div class="app-notice" style="margin-top:12px">${t('demoOnly')}</div></div>`)}
function simulateGuestScan(){const code=(document.getElementById('guestCodeInput')?.value||appState.guestCode).trim().toUpperCase(),codes={'AFE-OX-01':['oxford','ox-1'],'OX-01':['oxford','ox-1'],'AFE-OX-02':['oxford','ox-2'],'AFE-RB-A':['rosebank','rb-1'],'AFE-SC-04':['sandton','sc-1']},match=codes[code];if(!match){toast('Charger ID not recognized. Try AFE-OX-01.');return}const s=station(match[0]),c=s.connectors.find(x=>x.id===match[1]);if(!isStartable(s)||c?.status!=='Available'){toast('This demo connector is not available right now');return}appState.guestCode=code;appState.stationId=s.id;appState.connectorId=c.id;appState.guestLimit=200;appState.page='guest';render()}
function renderGuest(){const s=station(),c=connector(s);shell(`<button class="app-button ghost" onclick="showPage('scan')">‹ ${t('scanTitle')}</button><div class="app-card"><div class="app-row"><div><div class="app-small">${t('guestMode')}</div><h1>${esc(s.name)}</h1></div><span class="app-badge">GUEST</span></div><div class="app-muted">${esc(c.label)} · ${c.kw} kW · ${money(s.rate)} / kWh</div><div class="app-divider"></div><div class="app-kv"><span>Payment</span><b>${t('card')} · •••• ${esc(store.cardLast4)}</b></div><div class="app-notice">A simulated ${money(appState.guestLimit)} card pre-authorisation is shown below. No card data is sent or charged.</div><label class="app-label">Pre-authorisation amount</label><select class="app-select" id="guestLimitSelect" onchange="appState.guestLimit=Number(this.value)"><option value="100" ${appState.guestLimit===100?'selected':''}>R 100</option><option value="200" ${appState.guestLimit===200?'selected':''}>R 200</option><option value="300" ${appState.guestLimit===300?'selected':''}>R 300</option><option value="500" ${appState.guestLimit===500?'selected':''}>R 500</option></select><div class="app-kv"><span>Estimated card hold</span><b>${money(appState.guestLimit)}</b></div><div class="app-muted">After the session, the simulated charge is settled and any unused amount is released.</div></div><button class="app-button full" onclick="beginGuestConnection()">${t('authorise')} ${money(appState.guestLimit)} & ${t('start')} →</button><p class="app-muted" style="text-align:center">${t('demoOnly')}</p>`)}
function beginGuestConnection(){const s=station(),c=connector();appState.active={id:`AFE-G-${Date.now().toString().slice(-7)}`,stationId:s.id,connectorId:c.id,mode:'amount',limit:Number(appState.guestLimit),cap:Number(appState.guestLimit),energy:0,cost:0,started:Date.now(),customerType:'personal',payment:'card',preauth:Number(appState.guestLimit),guest:true};pushNotice('Guest session starting',s.name,`${c.label} · ${money(appState.guestLimit)} pre-authorisation`,appState.active.id);appState.page='guestConnecting';render();setTimeout(()=>{if(!appState.active||!appState.active.guest)return;appState.page='live';render();appState.tick=setInterval(tickSession,1500)},1500)}
function renderGuestConnecting(){shell(`<div class="app-card guest-connecting"><div class="connection-spinner"></div><h1>${t('connecting')}</h1><p class="app-muted">${esc(station().name)} · ${esc(connector().label)}</p><span class="app-badge">${t('demoOnly')}</span></div>`)}
function openStation(id){appState.stationId=id||appState.stationId;appState.page='station';render()}
function renderStation(){const s=station();shell(`<button class="app-button ghost" onclick="showPage('find')">‹ Back to stations</button><div class="app-row" style="margin-top:8px"><div><div class="app-small">STATION DETAILS</div><h1>${esc(s.name)}</h1></div><span class="app-badge">${availableCount(s)} available</span></div><p class="app-muted">${esc(s.address)} · ${esc(s.open)} · ${s.distance.toFixed(1)} km away</p><div class="app-card"><div class="app-row"><h3>Before you arrive</h3><strong>${money(s.rate)} / kWh</strong></div><div class="app-kv"><span>24h successful starts</span><b>${esc(s.lastSuccess)} · ${s.successRate}%</b></div><div class="app-kv"><span>Power access</span><b>${s.connectors.map(c=>c.powerType).filter((x,i,a)=>a.indexOf(x)===i).join(' / ')}</b></div><div class="app-row">${resilienceBadge(s)}<span class="app-small">${store.loadShedding&&s.resilience==='Grid only'?'Unavailable in load-shedding demo':'Load-shedding status: startable'}</span></div><div class="app-alert ${s.cable?'':'green'}">${s.cable?'Cable required for some bays.':'Tethered cable available on CCS bays.'} ${esc(s.parking)}</div><div class="app-row"><button class="app-button secondary" onclick="navigateToStation('${s.id}')">↗ Directions</button><button class="app-button secondary" onclick="chooseFailure()">Demo failure</button></div></div><div class="app-card"><div class="app-row"><h3>Station economics</h3>${resilienceBadge(s)}</div>${economyMarkup(s)}<div class="app-muted">Simulated CPO estimates for partner discussion; not financial guidance.</div></div><h2>Choose a connector</h2>${s.connectors.map(c=>{const available=c.status==='Available'&&!(store.loadShedding&&s.resilience==='Grid only');return `<div class="app-connector ${available?'':'disabled'}"><button onclick="${available?`selectConnector('${s.id}','${c.id}')`:'toast(\'This demo connector is currently unavailable\')'}"><div class="app-row"><b>${esc(c.label)}</b><span class="${available?'app-status':'app-small'}">${available?c.status:store.loadShedding&&s.resilience==='Grid only'?'Unavailable · load-shedding':c.status}</span></div><div class="app-muted">${c.type} · ${c.powerType} · ${c.kw} kW · ${c.cable?'Bring cable':'Cable supplied'}</div></button>${available?`<button class="app-button full" style="margin-top:9px" onclick="selectConnector('${s.id}','${c.id}')">Select this gun</button>`:''}</div>`}).join('')}<div class="app-alert">Open parking areas can have cable theft risk. Keep the cable attended while charging.</div><button class="app-button secondary full" onclick="showPage('setup')">Try a startup failure scenario</button>`)}
function selectConnector(sid,cid){appState.stationId=sid;appState.connectorId=cid;appState.page='setup';render()}
function chooseFailure(){appState.page='setup';appState.failure='communication';render();toast('Failure simulation selected. Start to view recovery options.')}
function renderSetup(){const s=station(),c=connector(s),estimate=appState.mode==='amount'?Number(appState.limit):appState.mode==='energy'?Number(appState.limit)*s.rate:Math.max(0,(Number(appState.limit)-35)*.9*s.rate),fleet=appState.customerType==='fleet';shell(`<button class="app-button ghost" onclick="showPage('station')">‹ ${esc(s.name)}</button><h1 style="margin-top:8px">Set charge limit</h1><p class="app-muted">${esc(c.label)} · ${c.kw} kW · ${money(s.rate)}/kWh · VAT included</p><div class="app-card"><div class="app-small">THIS SESSION IS FOR</div><div class="app-choice" style="margin-top:8px"><button class="${!fleet?'selected':''}" onclick="setCustomerType('personal')">Personal</button><button class="${fleet?'selected':''}" onclick="setCustomerType('fleet')">Fleet</button></div>${fleet?`<div class="app-notice fleet-note">Fleet account · ${esc(DEMO_DATA.fleet.vehicleId)} · ${esc(DEMO_DATA.fleet.plate)}<br>Charge is recorded to the fleet account. No card pre-authorisation. Settled monthly.</div>`:`<div class="app-muted" style="margin-top:8px">Personal session · payment is simulated at session end.</div>`}</div><div class="app-card"><div class="app-small">STOP WHEN I REACH</div><div class="app-choice" style="margin-top:8px"><button class="${appState.mode==='amount'?'selected':''}" onclick="setMode('amount')">Amount</button><button class="${appState.mode==='energy'?'selected':''}" onclick="setMode('energy')">Energy</button><button class="${appState.mode==='soc'?'selected':''}" onclick="setMode('soc')">Battery %</button></div><label class="app-label">${appState.mode==='amount'?'Maximum spend (ZAR)':appState.mode==='energy'?'Energy (kWh)':'Target battery (%)'}</label><input class="app-input" id="limitInput" type="number" min="1" max="${appState.mode==='soc'?100:2000}" value="${esc(appState.limit)}" oninput="appState.limit=this.value;updateEstimate()"><div id="estimateLine" class="app-kv"><span>${fleet?'Fleet spend limit · no card hold':'Estimated card pre-authorisation'}</span><b>${money(estimate)}</b></div><div class="app-muted">Final demo total follows meter energy. ${fleet?'Session amount is added to the month-end fleet statement.':'Unused card authorisation is shown as released.'}</div></div>${fleet?`<div class="app-card"><div class="app-row"><h3>Fleet month-to-date</h3><span class="app-badge">SIMULATED</span></div><div class="app-kv"><span>${t('vehicle')}</span><b>${esc(DEMO_DATA.fleet.vehicleId)} · ${esc(DEMO_DATA.fleet.plate)}</b></div><div class="app-kv"><span>Previous demo sessions</span><b>${DEMO_DATA.fleet.priorSessions} · ${DEMO_DATA.fleet.priorEnergy} kWh</b></div><div class="app-kv"><span>Month-to-date amount</span><b>${money(DEMO_DATA.fleet.priorAmount)}</b></div><button class="app-button secondary full" onclick="showPage('fleet')">View monthly statement →</button></div>`:`<div class="app-card"><h3>Payment method</h3><div class="app-connector ${appState.payment==='card'?'selected':''}"><button onclick="setPayment('card')"><div class="app-row"><b>Visa •••• ${esc(store.cardLast4)}</b><span>${appState.payment==='card'?'✓ Selected':''}</span></div><div class="app-muted">Card on file · simulated pre-authorisation</div></button></div><div class="app-connector ${appState.payment==='wallet'?'selected':''}"><button onclick="setPayment('wallet')"><div class="app-row"><b>Wallet · ${money(store.wallet)}</b><span>${appState.payment==='wallet'?'✓ Selected':''}</span></div><div class="app-muted">Prepaid demo balance · no card hold</div></button></div><button class="app-button ghost" onclick="setFailure()">⚙ ${appState.failure==='none'?'Set demo failure scenario':`Failure test: ${failureLabel()}`}</button></div>`}<div class="app-notice">DEMO · No real charging or payment. Plug status and settlement are simulated.</div><button class="app-button full" onclick="startSession()">${fleet?'Add to fleet account & start demo →':'Authorise & start demo session →'}</button>`)}
function setCustomerType(type){appState.customerType=type;renderSetup()}
function setMode(mode){const input=document.getElementById('limitInput');if(input)appState.limit=input.value;appState.mode=mode;renderSetup()}
function setPayment(mode){appState.payment=mode;store.payment=mode;saveStore();renderSetup()}
function updateEstimate(){const el=document.getElementById('estimateLine');if(!el)return;const s=station(),v=Number(appState.limit)||0,e=appState.mode==='amount'?v:appState.mode==='energy'?v*s.rate:Math.max(0,(v-35)*.9*s.rate);el.innerHTML=`<span>Estimated pre-authorisation</span><b>${money(e)}</b>`}
function setFailure(){const options=['none','gun','communication','payment'];const i=options.indexOf(appState.failure);appState.failure=options[(i+1)%options.length];renderSetup();toast(`Failure scenario: ${failureLabel()}`)}
function failureLabel(){return{none:'Off',gun:'Gun fault',communication:'Communication timeout',payment:'Pre-authorisation declined'}[appState.failure]}
function startSession(){const s=station(),c=connector(),v=Number(appState.limit);if(!v||v<1){toast('Enter a valid charge limit');return}if(!isStartable(s)||c.status!=='Available'){toast('This station is not startable in the current demo scenario');return}if(appState.customerType==='personal'&&appState.failure!=='none'){appState.page='failure';render();return}const cap=appState.mode==='amount'?v:appState.mode==='energy'?v*s.rate:Math.max(20,(v-35)*.9*s.rate),fleet=appState.customerType==='fleet';appState.active={id:`AFE-${Date.now().toString().slice(-7)}`,stationId:s.id,connectorId:c.id,mode:appState.mode,limit:v,cap:cap,energy:0,cost:0,started:Date.now(),customerType:appState.customerType,payment:fleet?'fleet':appState.payment,preauth:!fleet&&appState.payment==='card'?cap:0,fleetVehicleId:fleet?DEMO_DATA.fleet.vehicleId:null,fleetPlate:fleet?DEMO_DATA.fleet.plate:null};pushNotice('Charging started',`${s.name} · ${c.label}`,`${money(0)} · 0.0 kWh`,appState.active.id);appState.page='live';render();appState.tick=setInterval(tickSession,1500)}
function renderFailure(){const why={gun:['Connector reports a fault','Try the other available CCS gun or choose another station.'],communication:['Charger did not respond in time','Check the connector is seated, then retry or use another gun.'],payment:['Card pre-authorisation was declined','Choose wallet or retry with the demo card.']}[appState.failure]||['Unable to start','Try again.'];shell(`<button class="app-button ghost" onclick="showPage('setup')">‹ Back to startup</button><div class="app-card"><div class="app-badge" style="background:#fff0ee;color:#a34339">START FAILED · DEMO</div><h1 style="margin-top:10px">${why[0]}</h1><p class="app-muted">${why[1]}</p><div class="app-alert red">No session started and no payment was taken.</div><button class="app-button full" onclick="retryStart()">Retry start</button><button class="app-button secondary full" style="margin-top:8px" onclick="switchBackupGun()">Switch to backup gun</button><button class="app-button secondary full" style="margin-top:8px" onclick="switchBackupStation()">Switch to backup station</button><button class="app-button ghost full" onclick="alternativeStart()">Try QR / card start (demo placeholder)</button></div><button class="app-button ghost" onclick="showPage('station')">View station details</button>`)}
function retryStart(){appState.failure='none';startSession()}
function switchBackupGun(){const s=station(),other=s.connectors.find(c=>c.status==='Available'&&c.id!==appState.connectorId);if(other){appState.connectorId=other.id;appState.failure='none';appState.page='setup';render();toast(`Switched to ${other.label}`)}else switchBackupStation()}
function switchBackupStation(){const other=DEMO_DATA.stations.find(s=>s.id!==appState.stationId&&s.available>0);if(!other){toast('No backup station available');return}appState.stationId=other.id;appState.connectorId=connector(other).id;appState.failure='none';appState.page='setup';render();toast(`Switched to ${other.name}`)}
function alternativeStart(){appState.failure='none';toast('Demo QR/card method selected');startSession()}
function tickSession(){if(!appState.active)return;const a=appState.active,s=station(a.stationId);a.energy=Number((a.energy+.18).toFixed(2));a.cost=Number((a.energy*s.rate).toFixed(2));if(a.cost>=a.cap){a.cost=Number(a.cap.toFixed(2));a.energy=Number((a.cost/s.rate).toFixed(2));finishSession('Limit reached');return}renderLive()}
function advanceDemo(){if(!appState.active)return;appState.active.energy=Number((appState.active.energy+5).toFixed(2));appState.active.cost=Number((appState.active.energy*station().rate).toFixed(2));if(appState.active.cost>=appState.active.cap){appState.active.cost=Number(appState.active.cap.toFixed(2));appState.active.energy=Number((appState.active.cost/station().rate).toFixed(2));finishSession('Limit reached')}else renderLive()}
function adjustLiveLimit(){if(appState.tick)clearInterval(appState.tick);appState.page='liveLimit';renderLiveLimit()}
function renderLiveLimit(){const a=appState.active;if(!a)return renderHome();shell(`<button class="app-button ghost" onclick="appState.page='live';appState.tick=setInterval(tickSession,1500);renderLive()">‹ Back to session</button><h1 style="margin-top:8px">Adjust session limit</h1><div class="app-card"><div class="app-kv"><span>Already used</span><b>${money(a.cost)}</b></div><label class="app-label">New maximum spend (R)</label><input class="app-input" id="newLiveLimit" type="number" min="${Math.ceil(a.cost+1)}" value="${Math.ceil(a.cap+20)}"><div class="app-muted" style="margin-top:8px">The new limit must be higher than the amount already used.</div></div><button class="app-button full" onclick="applyLiveLimit()">Save new limit</button>`)}
function applyLiveLimit(){const a=appState.active,n=Number(document.getElementById('newLiveLimit')?.value);if(!a||!n||n<=a.cost){toast('Enter a limit higher than amount used');return}a.cap=n;a.limit=n;if(a.payment==='card')a.preauth=n;appState.page='live';appState.tick=setInterval(tickSession,1500);renderLive()}
function renderLive(){if(!appState.active)return;const a=appState.active,s=station(a.stationId),remaining=Math.max(0,a.cap-a.cost),pct=Math.min(100,a.cost/a.cap*100);shell(`<div class="app-row"><div><div class="app-small">DEMO SESSION · ${esc(a.id)}</div><h1>Charging now</h1></div><span class="app-badge">Connected · demo</span></div><div class="app-card app-recommend"><div class="app-small" style="color:#cce0d2">${esc(s.name)} · ${esc(connector(s,a.connectorId).label)}</div><div class="app-amount" style="font-size:44px;margin:9px 0">${a.energy.toFixed(1)} <span style="font-size:14px">kWh</span></div><div class="app-muted">Current demo cost · ${money(a.cost)}</div><div class="app-progress" style="margin-top:13px"><i style="width:${pct}%"></i></div></div><div class="app-inline"><div class="app-stat">Used<b>${money(a.cost)}</b></div><div class="app-stat">Remaining limit<b>${money(remaining)}</b></div><div class="app-stat">Battery<b>${Math.min(95,42+Math.floor(a.energy))}%</b></div></div><div class="app-card"><div class="app-row"><h3>Charge limit</h3><b>${money(a.cap)}</b></div><p class="app-muted">Limit control remains active during this demo session.</p><button class="app-button secondary full" onclick="adjustLiveLimit()">Adjust amount limit</button><button class="app-button ghost full" onclick="advanceDemo()">Advance demo by 5 kWh</button></div><button class="app-button danger full" onclick="finishSession('Stopped by driver')">Stop charging</button><p class="app-muted" style="text-align:center">Simulation updates about every 1.5 seconds. No vehicle or charger is controlled.</p>`)}
function finishSession(reason){if(!appState.active)return;if(appState.tick)clearInterval(appState.tick);const a=appState.active,s=station(a.stationId),now=Date.now(),actual=Number(a.cost.toFixed(2)),pre=a.payment==='card'?a.preauth:0,release=Number(Math.max(0,pre-actual).toFixed(2));if(a.payment==='wallet')store.wallet=Math.max(0,store.wallet-actual);const rec={...a,ended:now,duration:Math.max(1,Math.round((now-a.started)/60000)),actual,release,reason,status:'Complete',transaction:`TX-${now.toString().slice(-8)}`,stationName:s.name,area:s.area,rate:s.rate,connectorLabel:connector(s,a.connectorId).label,invoice:`AFE-${now.toString().slice(-8)}`};store.history.unshift(rec);appState.recordId=rec.id;appState.active=null;appState.page='summary';saveStore();pushNotice('Charging ended',s.name,`${money(actual)} · ${rec.energy.toFixed(1)} kWh`,rec.id);pushNotice(a.customerType==='fleet'?'Fleet account updated':'Payment successful',s.name,a.customerType==='fleet'?`${money(actual)} · added to monthly statement`:`${money(actual)} · ${a.payment==='wallet'?'Wallet':`Visa •••• ${esc(store.cardLast4)}`}`,rec.id);pushNotice('Receipt generated',s.name,`Invoice ${rec.invoice}`,rec.id);saveStore();render()}
function currentRecord(){return store.history.find(x=>x.id===appState.recordId)||store.history[0]}
function renderSummary(){const r=currentRecord();if(!r)return renderHistory();const vat=Number((r.actual*DEMO_DATA.vatRate/(1+DEMO_DATA.vatRate)).toFixed(2)),subtotal=Number((r.actual-vat).toFixed(2)),fleet=r.customerType==='fleet';shell(`<div class="app-row"><button class="app-button ghost" onclick="showPage('history')">‹ History</button><span class="app-badge">DEMO TRANSACTION</span></div><div class="app-card" style="text-align:center"><div class="app-badge">SESSION COMPLETE</div><h1 style="margin-top:10px">${fleet?'Fleet session summary':'Payment summary'}</h1><div class="app-amount" style="margin:12px 0">${money(r.actual)}</div><div class="app-muted">${esc(r.stationName)} · ${new Date(r.ended).toLocaleString('en-ZA',{timeZone:'Africa/Johannesburg'})}</div></div><div class="app-card"><h3>Session</h3><div class="app-kv"><span>Energy · duration</span><b>${r.energy.toFixed(1)} kWh · ${r.duration} min</b></div><div class="app-kv"><span>Limit</span><b>${money(r.cap)}</b></div><div class="app-kv"><span>Stop reason</span><b>${esc(r.reason)}</b></div><div class="app-divider"></div><h3>${fleet?'Fleet account ledger':'Payment reconciliation'}</h3><div class="app-kv"><span>${fleet?'Card pre-authorisation':'Pre-authorised'}</span><b>${money(r.preauth)}</b></div><div class="app-kv"><span>${fleet?'Added to monthly account':'Actual consumption'}</span><b>${money(r.actual)}</b></div><div class="app-kv"><span>${fleet?'Card release':'Released'}</span><b>${fleet?'Not applicable':money(r.release)}</b></div><div class="app-kv"><span>Payment path</span><b>${fleet?'Fleet account · month-end settlement':r.payment==='wallet'?'Prepaid wallet':`Visa •••• ${esc(store.cardLast4)}`}</b></div><div class="app-kv"><span>Transaction</span><b>${esc(r.transaction)}</b></div><div class="app-kv"><span>Subtotal</span><b>${money(subtotal)}</b></div><div class="app-kv"><span>VAT (15%)</span><b>${money(vat)}</b></div></div><div class="app-alert green">${fleet?'Fleet charge recorded for month-end settlement. No payment was made in this demo.':'Demo transaction · no money was charged. '+(r.payment==='card'?`${money(r.release)} of the simulated authorisation is released.`:'Wallet balance reflects this demo session.')}</div><button class="app-button full" onclick="openInvoice('${r.id}')">View simulated invoice / receipt</button>${fleet?'<button class="app-button secondary full" style="margin-top:8px" onclick="showPage(\'fleet\')">Open fleet monthly statement →</button>':''}<button class="app-button secondary full" style="margin-top:8px" onclick="showPage('history')">Go to charging history</button>`)}
function renderHistory(){shell(`<div class="app-row"><div><div class="app-small">YOUR ACTIVITY</div><h1>Charging history</h1></div><span class="app-badge">${store.history.length} sessions</span></div>${store.history.some(r=>r.customerType==='fleet')?'<button class="app-button secondary full" onclick="showPage(\'fleet\')">Fleet monthly statement →</button>':''}${store.history.length?store.history.map(r=>`<article class="app-card app-station" onclick="openRecord('${r.id}')"><div class="app-row"><b>${esc(r.stationName)}</b><span class="app-badge">${r.customerType==='fleet'?'FLEET · ':''}${esc(r.status)}</span></div><div class="app-muted">${new Date(r.ended).toLocaleString('en-ZA',{timeZone:'Africa/Johannesburg'})} · ${r.duration} min</div><div class="app-row" style="margin-top:10px"><span>${r.energy.toFixed(1)} kWh · ${esc(r.connectorLabel)}</span><b>${money(r.actual)}</b></div></article>`).join(''):'<div class="app-card app-empty">No demo sessions yet. Start a session to create a history record.</div>'}`)}
function openRecord(id){appState.recordId=id;appState.page='summary';render()}
function openInvoice(id){appState.recordId=id;appState.page='invoice';render()}
function renderInvoice(){const r=currentRecord();if(!r)return renderHistory();const vat=Number((r.actual*.15/1.15).toFixed(2)),subtotal=Number((r.actual-vat).toFixed(2));shell(`<button class="app-button ghost" onclick="openRecord('${r.id}')">‹ Payment summary</button><div class="app-card"><div class="app-row"><div class="app-brand"><span class="app-brandmark">ϟ</span>AFE Charge</div><span class="app-badge">DEMO</span></div><h1 style="margin-top:16px">Tax invoice preview</h1><div class="app-muted">Not a tax document · simulated only</div><div class="app-divider"></div><div class="app-kv"><span>Invoice number</span><b>${esc(r.invoice)}</b></div><div class="app-kv"><span>Transaction</span><b>${esc(r.transaction)}</b></div><div class="app-kv"><span>Station</span><b>${esc(r.stationName)}</b></div><div class="app-kv"><span>Energy delivered</span><b>${r.energy.toFixed(1)} kWh</b></div><div class="app-divider"></div><div class="app-kv"><span>Subtotal</span><b>${money(subtotal)}</b></div><div class="app-kv"><span>VAT (15%)</span><b>${money(vat)}</b></div><div class="app-kv"><span>Total</span><b>${money(r.actual)}</b></div></div><div class="app-notice">Simulation receipt only. No VAT invoice has been issued.</div>`)}
function pushNotice(title,site,summary,recordId){store.notifications.unshift({id:`N-${Date.now()}-${Math.random().toString(16).slice(2,5)}`,title,site,summary,recordId,created:Date.now(),read:false})}
function renderNotifications(){shell(`<div class="app-row"><div><div class="app-small">ACTIVITY CENTRE</div><h1>Notifications</h1></div><button class="app-button ghost" onclick="store.notifications.forEach(n=>n.read=true);saveStore();renderNotifications()">Mark all read</button></div>${store.notifications.length?store.notifications.map(n=>`<article class="app-card app-station" onclick="openNotice('${n.id}')"><div class="app-row"><b>${esc(n.title)}</b>${n.read?'':'<span class="app-badge">NEW</span>'}</div><div class="app-muted">${esc(n.site)} · ${new Date(n.created).toLocaleTimeString('en-ZA',{hour:'2-digit',minute:'2-digit',timeZone:'Africa/Johannesburg'})}</div><div style="font-size:11px;margin-top:7px">${esc(n.summary)}</div></article>`).join(''):'<div class="app-card app-empty">No notifications yet. Charging events appear here.</div>'}`)}
function openNotice(id){const n=store.notifications.find(x=>x.id===id);if(!n)return;n.read=true;saveStore();if(n.recordId){appState.recordId=n.recordId;appState.page='summary';render()}else renderNotifications()}
function renderProfile(){shell(`<div class="app-row"><div><div class="app-small">YOUR ACCOUNT</div><h1>${t('me')}</h1></div></div><div class="app-card"><div class="app-row"><div><h3>${t('wallet')}</h3><div class="app-amount" style="margin:8px 0">${money(store.wallet)}</div></div><span class="app-badge">+R 50 on R 500</span></div><button class="app-button full" onclick="showPage('wallet')">${t('topUp')} · ${money(store.wallet)} →</button></div><div class="app-card"><div class="app-row"><h3>${t('payment')}</h3><span class="app-badge">${store.payment==='card'?'Card':'Wallet'}</span></div><div class="app-muted">Choose simulated card or prepaid wallet before a personal session.</div><button class="app-button secondary full" style="margin-top:10px" onclick="showPage('payments')">${t('payment')} methods</button><button class="app-button ghost full" onclick="showPage('cardForm')">＋ Bind a new card</button></div><div class="app-card"><div class="app-row"><div><h3>Fleet customer</h3><div class="app-muted">Monthly account summary · demo only</div></div><span class="app-badge">B2B</span></div><button class="app-button secondary full" style="margin-top:10px" onclick="showPage('fleet')">Fleet monthly statement →</button></div><div class="app-card settings-links"><button class="app-menu" onclick="showPage('settings')">⚙ ${t('settings')} <span>›</span></button><button class="app-menu" onclick="showPage('help')">ⓘ ${t('help')} <span>›</span></button><button class="app-menu" onclick="showPage('emergency')">! ${t('emergency')} <span>›</span></button><button class="app-menu" onclick="showPage('feedback')">✉ ${t('feedback')} <span>›</span></button></div><div class="app-card"><h3>Demo data</h3><div class="app-muted" style="margin:7px 0 12px">Clear local history, notifications, wallet and preferences from this device.</div><button class="app-button danger full" onclick="clearDemoData()">Clear demo data</button></div><div class="app-notice">${t('demoOnly')}</div>`)}
function renderSettings(){shell(`<button class="app-button ghost" onclick="showPage('profile')">‹ ${t('me')}</button><h1>${t('settings')}</h1><div class="app-card"><h3>${t('appearance')}</h3><label class="app-label">${t('appearance')}</label><select class="app-select" onchange="setTheme(this.value)"><option value="light" ${store.theme==='light'?'selected':''}>☀ ${t('light')}</option><option value="dark" ${store.theme==='dark'?'selected':''}>☾ ${t('dark')}</option></select><label class="app-label">${t('font')}</label><select class="app-select" onchange="setFontSize(this.value)"><option value="small" ${store.fontSize==='small'?'selected':''}>Small</option><option value="medium" ${store.fontSize==='medium'?'selected':''}>Medium</option><option value="large" ${store.fontSize==='large'?'selected':''}>Large</option></select><label class="app-label">${t('language')}</label><select class="app-select" onchange="setLanguage(this.value)"><option value="en" ${store.language==='en'?'selected':''}>English</option><option value="af" ${store.language==='af'?'selected':''}>Afrikaans</option><option value="zu" ${store.language==='zu'?'selected':''}>isiZulu</option><option value="zh" ${store.language==='zh'?'selected':''}>简体中文</option></select></div><div class="app-card"><h3>More help</h3><button class="app-menu" onclick="showPage('emergency')">${t('emergency')} <span>›</span></button><button class="app-menu" onclick="showPage('feedback')">${t('feedback')} <span>›</span></button></div>`)}
function setTheme(theme){store.theme=theme==='dark'?'dark':'light';saveStore();render()}
function setFontSize(size){store.fontSize=['small','large'].includes(size)?size:'medium';saveStore();renderSettings()}
function setLanguage(language){store.language=I18N[language]?language:'en';saveStore();render()}
function renderEmergency(){shell(`<button class="app-button ghost" onclick="showPage('settings')">‹ ${t('settings')}</button><div class="app-card emergency-card"><div class="app-badge">SAFETY GUIDE · DEMO</div><h1>${t('emergency')}</h1><p class="app-muted">If a connector will not release, stop the session in the app first. Do not pull, pry or force the connector.</p><div class="app-step"><b>1</b><span>Stop charging and wait for the connector lock to release.</span></div><div class="app-step"><b>2</b><span>Look for the charger’s clearly labelled emergency release port or instructions. Follow only the instructions printed on that charger.</span></div><div class="app-step"><b>3</b><span>If there is no labelled release, or it still feels stuck, leave it in place and contact the site operator. Do not insert tools into unlabelled holes.</span></div><div class="app-alert">Smoke, heat, sparks or injury: move away and call local emergency services.</div><button class="app-button full" onclick="toast('Demo call · customer support number has not been configured')">☎ Call AFE support · demo</button></div>`)}
function renderFeedback(){shell(`<button class="app-button ghost" onclick="showPage('settings')">‹ ${t('settings')}</button><h1>${t('feedback')}</h1><div class="app-card"><label class="app-label">Tell us what happened</label><textarea class="app-input" id="feedbackText" rows="5" maxlength="1000" placeholder="Your feedback stays on this device in this demo."></textarea><label class="app-label">Attach image (optional)</label><input class="app-input" id="feedbackImage" type="file" accept="image/*" onchange="document.getElementById('feedbackFileName').textContent=this.files?.[0]?.name||'No image selected'"><div id="feedbackFileName" class="app-muted">Image is a local placeholder and will not be uploaded.</div><button class="app-button full" style="margin-top:14px" onclick="submitFeedback()">Submit feedback</button><div class="app-notice" style="margin-top:12px">Demo feedback is saved locally only; nothing is sent.</div></div>`)}
function submitFeedback(){const text=(document.getElementById('feedbackText')?.value||'').trim();if(!text){toast('Please enter a short message');return}store.feedback.unshift({text,created:Date.now(),imageName:document.getElementById('feedbackImage')?.files?.[0]?.name||''});saveStore();toast('Feedback received · demo only');showPage('settings')}
function renderHelp(){shell(`<button class="app-button ghost" onclick="showPage('profile')">‹ ${t('me')}</button><div class="app-small">AFE CHARGE</div><h1>${t('help')}</h1><div class="app-card"><h3>How to scan and charge</h3><ol class="help-list"><li>Tap the centre Scan button, then enter the charger ID or use the demo QR action.</li><li>Check the connector and price, set a limit, and choose Personal or Fleet.</li><li>Start the demo session, adjust the limit or stop, then review the settlement summary.</li></ol></div><div class="app-card"><h3>How to find past bills</h3><ol class="help-list"><li>Open ${t('history')} in the bottom bar.</li><li>Tap a session to see its payment summary and simulated receipt.</li></ol></div><div class="app-card faq-card"><h3>Frequently asked questions</h3><details><summary>Does this app start a real charger?</summary><p>No. This is a demo with mock station and session data.</p></details><details><summary>Will my card be charged?</summary><p>No. Card authorisation and settlement are simulated in this demo.</p></details><details><summary>Why can’t I see the Google map?</summary><p>The site owner must add a Google Maps browser key in config.js and enable Maps JavaScript API.</p></details><details><summary>What if a connector is stuck?</summary><p>Stop the session, follow only the charger’s labelled release instructions, and contact site support. Do not force it.</p></details></div>`)}
function renderFleetStatement(){const rows=store.history.filter(r=>r.customerType==='fleet'),count=DEMO_DATA.fleet.priorSessions+rows.length,kwh=DEMO_DATA.fleet.priorEnergy+rows.reduce((sum,r)=>sum+r.energy,0),amount=DEMO_DATA.fleet.priorAmount+rows.reduce((sum,r)=>sum+r.actual,0),status=rows.length?'Awaiting month-end settlement · demo':'Open demo statement · no charge posted';shell(`<button class="app-button ghost" onclick="showPage('profile')">‹ Account</button><div class="app-card fleet-statement"><div class="app-row"><div><div class="app-small">AFE CHARGE · FLEET</div><h1>Monthly statement</h1></div><span class="app-badge">DEMO</span></div><div class="app-muted">Statement for a fleet customer · no real account or invoice</div><div class="app-divider"></div><div class="app-kv"><span>Vehicle / plate</span><b>${esc(DEMO_DATA.fleet.vehicleId)} · ${esc(DEMO_DATA.fleet.plate)}</b></div><div class="app-kv"><span>Charging sessions</span><b>${count}</b></div><div class="app-kv"><span>Total energy</span><b>${kwh.toFixed(1)} kWh</b></div><div class="app-kv"><span>Settlement cycle</span><b>${esc(DEMO_DATA.fleet.cycle)}</b></div><div class="app-divider"></div><div class="app-kv statement-total"><span>Amount due · simulated</span><b>${money(amount)}</b></div><div class="app-alert ${rows.length?'':'green'}">Payment status: ${esc(status)}</div></div><div class="app-card"><h3>What AFE provides to a fleet</h3><div class="app-muted">Each driver charge is attached to a vehicle, recorded with kWh and amount, then grouped into a monthly statement for account reconciliation.</div>${rows.map(r=>`<div class="app-kv"><span>${esc(r.stationName)} · ${r.energy.toFixed(1)} kWh</span><b>${money(r.actual)}</b></div>`).join('')}</div><div class="app-notice">Simulation only · this statement does not request or collect payment.</div>`)}
function renderPayments(){shell(`<button class="app-button ghost" onclick="showPage('profile')">‹ ${t('me')}</button><h1>${t('payment')} methods</h1><div class="app-notice">Simulated payment state only · no money is charged.</div><div class="app-card"><div class="app-connector ${store.payment==='card'?'selected':''}" onclick="setPaymentPref('card')"><div class="app-row"><b>Visa •••• ${esc(store.cardLast4)}</b><span>${store.payment==='card'?'✓':''}</span></div><div class="app-muted">Simulated card authorisation and release</div></div><div class="app-connector ${store.payment==='wallet'?'selected':''}" onclick="setPaymentPref('wallet')"><div class="app-row"><b>${t('wallet')} · ${money(store.wallet)}</b><span>${store.payment==='wallet'?'✓':''}</span></div><div class="app-muted">Session amount is deducted from demo balance</div></div><button class="app-button secondary full" onclick="showPage('cardForm')">＋ Bind a new card</button></div>`)}
function renderCardForm(){shell(`<button class="app-button ghost" onclick="showPage('payments')">‹ ${t('payment')}</button><h1>Bind a card · demo</h1><div class="app-notice">Use fictional test values only. This form does not send or store the full card number, expiry or CVV.</div><div class="app-card"><label class="app-label">Card number</label><input id="newCardNumber" class="app-input" inputmode="numeric" autocomplete="off" maxlength="23" placeholder="4242 4242 4242 4242"><div class="app-row"><label class="form-stack"><span>Expiry</span><input id="newCardExpiry" class="app-input" inputmode="numeric" autocomplete="off" maxlength="5" placeholder="MM/YY"></label><label class="form-stack"><span>CVV</span><input id="newCardCvv" class="app-input" inputmode="numeric" autocomplete="off" maxlength="4" placeholder="123"></label></div><button class="app-button full" style="margin-top:14px" onclick="saveDemoCard()">Save demo card</button></div>`)}
function saveDemoCard(){const digits=(document.getElementById('newCardNumber')?.value||'').replace(/\D/g,''),expiry=(document.getElementById('newCardExpiry')?.value||'').trim(),cvv=(document.getElementById('newCardCvv')?.value||'').replace(/\D/g,'');if(digits.length<13||digits.length>19){toast('Enter a 13–19 digit demo card number');return}if(!/^(0[1-9]|1[0-2])\/\d{2}$/.test(expiry)){toast('Expiry must use MM/YY');return}if(cvv.length<3||cvv.length>4){toast('CVV must be 3–4 digits');return}store.cardLast4=digits.slice(-4);store.payment='card';appState.payment='card';saveStore();toast('Demo card saved · full details were discarded');showPage('payments')}
function setPaymentPref(p){store.payment=p;appState.payment=p;saveStore();renderPayments()}
function topUp(){store.wallet+=100;saveStore();renderProfile();toast('R 100 demo funds added')}
function renderWallet(){const offers=[{amount:100,bonus:0},{amount:500,bonus:50},{amount:1000,bonus:125}];shell(`<button class="app-button ghost" onclick="showPage('profile')">‹ ${t('me')}</button><div class="app-row"><div><div class="app-small">AFE CHARGE</div><h1>${t('wallet')}</h1></div><span class="app-badge">DEMO</span></div><div class="app-card wallet-hero"><div class="app-small">LOCAL DEMO BALANCE</div><div class="app-amount" style="font-size:32px;margin:8px 0">${money(store.wallet)}</div><div class="app-muted">Balance and top-up history stay on this device.</div></div><div class="app-card"><h3>Electric card benefits</h3><ul class="help-list"><li>R 500 top-up includes R 50 demo bonus.</li><li>Illustrative member-rate discount: 5% on sample public rates.</li><li>Top-ups do not charge a bank card in this prototype.</li></ul></div><h2>Choose a top-up</h2>${offers.map(o=>`<div class="app-card app-topup-row"><div><b>${money(o.amount)}</b><div class="app-muted">${o.bonus?`Bonus ${money(o.bonus)} · total ${money(o.amount+o.bonus)}`:'No bonus'}</div></div><button class="app-button" onclick="topUpWallet(${o.amount},${o.bonus})">${t('topUp')}</button></div>`).join('')}<div class="app-notice">${t('demoOnly')}</div>`)}
function topUpWallet(amount,bonus){store.wallet+=amount+bonus;store.walletLedger.unshift({amount,bonus,created:Date.now(),demo:true});saveStore();toast(`Demo top-up successful · ${money(amount+bonus)} added`);renderWallet()}
function clearDemoData(){if(!confirm('Clear demo sessions, notifications, wallet and preferences on this device?'))return;try{localStorage.removeItem(STORE_KEY)}catch(error){console.warn('AFE Charge: local storage unavailable',error)}store=loadStore();appState.page='find';render();toast('Demo data cleared')}
function openFilters(){document.getElementById('overlayRoot').innerHTML=`<div class="app-filter" onclick="if(event.target===this)closeFilters()"><section class="app-sheet"><div class="app-row"><h2>Filter stations</h2><button class="app-button ghost" onclick="closeFilters()">Close</button></div><label class="app-label">Connector</label><select class="app-select" id="filterConnector" onchange="setFilter('connector',this.value)">${['Any','CCS','CHAdeMO','Type 2'].map(x=>`<option ${x===appState.filter.connector?'selected':''}>${x}</option>`).join('')}</select><label class="app-label">Power type</label><select class="app-select" id="filterPower" onchange="setFilter('power',this.value)">${['Any','AC','DC'].map(x=>`<option ${x===appState.filter.power?'selected':''}>${x}</option>`).join('')}</select><label class="app-inline" style="margin:14px 0;font-size:11px"><input type="checkbox" ${appState.filter.recent?'checked':''} onchange="setFilter('recent',this.checked)"> Only recently startable stations</label><label class="app-inline" style="margin:8px 0 14px;font-size:11px"><input type="checkbox" ${appState.filter.sort?'checked':''} onchange="setFilter('sort',this.checked)"> Sort by last 24h success rate</label><button class="app-button full" onclick="closeFilters()">Show ${filteredStations().length} stations</button><button class="app-button ghost full" onclick="appState.filter={connector:'Any',power:'Any',recent:false,sort:false};renderHome()">Reset filters</button></section></div>`}
function setFilter(k,v){appState.filter[k]=v;openFilters()}
function closeFilters(){document.getElementById('overlayRoot').innerHTML='';renderHome()}
function toast(msg){const root=document.getElementById('toastRoot');if(!root)return;root.innerHTML=`<div class="app-toast">${esc(msg)}</div>`;clearTimeout(appState.toastTimer);appState.toastTimer=setTimeout(()=>{if(root)root.innerHTML=''},2400)}
function bindHomeSearch(){const h=document.querySelector('.app-main h1');}
function initApp(){document.querySelector('.appview').innerHTML='<div id="afe-app-mount"></div>';render();window.addEventListener('online',render);window.addEventListener('offline',render)}
const COPY_TABLE=window.AFE_I18N.copy;;
const routeStack=['find'];
function translateMarkup(html){if(store.language==='en')return String(html);let out=String(html);const dict=COPY_TABLE[store.language]||{};for(const [en,value] of Object.entries(dict).sort((a,b)=>b[0].length-a[0].length))out=out.split(en).join(value);return out}
function applyPreferences(){document.documentElement.dataset.theme=store.theme;document.documentElement.dataset.fontSize=store.fontSize;document.documentElement.lang=({en:'en',af:'af',zu:'zu',zh:'zh-CN'})[store.language]||'en';document.documentElement.style.colorScheme=store.theme==='dark'?'dark':'light';const meta=document.querySelector('meta[name=theme-color]');if(meta)meta.content=store.theme==='dark'?'#0d1511':'#f4f7f4'}
function saveStore(){try{localStorage.setItem(STORE_KEY,JSON.stringify(store));return true}catch(error){console.warn('AFE Charge: local storage unavailable',error);return false}}
function shell(content){applyPreferences();const mount=document.querySelector('.appview');const wrapper=document.createElement('div');wrapper.className='app-root';wrapper.dataset.fontSize=store.fontSize;wrapper.innerHTML=translateMarkup(appHeader())+`<main class="app-main">${translateMarkup(content)}</main>${nav()}<div id="overlayRoot"></div><div id="toastRoot"></div>`;mount.replaceChildren(wrapper)}
function showPage(page){if(page===appState.page)return;try{routeStack.push(page);history.pushState({afePage:page},'',`#${page}`)}catch{}appState.page=page;render()}
function setTheme(theme){store.theme=theme==='dark'?'dark':'light';saveStore();render()}
function setFontSize(size){store.fontSize=['small','medium','large'].includes(size)?size:'medium';saveStore();render()}
function setLanguage(language){store.language=I18N[language]?language:'en';saveStore();render()}
function renderMapView(){const s=appState.selectedMarker?station(appState.selectedMarker):null;const points=[['oxford',25,53],['rosebank',54,34],['sandton',76,67]];const markers=points.map(([id,left,top])=>{const st=station(id);return `<button class="afe-map-marker" style="left:${left}%;top:${top}%" aria-label="${esc(st.name)} · ${availableCount(st)} ${t('available')}" onclick="showMapStation('${id}')"><span>${availableCount(st)}</span></button>`}).join('');const background=window.AFE_CONFIG?.GOOGLE_MAPS_API_KEY?'<div class="map-loading">Loading Google Maps…</div>':`<div class="afe-map-fallback" aria-label="Illustrated station map">${markers}<div class="map-key-notice"><b>${t('location')}</b><span>${t('mapUnavailable')}</span></div></div>`;return `<section class="app-map-wrap"><div id="afeMap" class="app-map-canvas">${background}</div><div id="mapSheetRoot">${s?mapStationSheet(s):`<div class="app-card map-bottom-sheet"><span class="app-small">${t('location')}</span><div class="app-muted">${t('mapHint')}</div></div>`}</div></section>`}
function mapStationSheet(s){return `<div class="app-card map-bottom-sheet"><div class="app-row"><div><h3>${esc(s.name)}</h3><div class="app-muted">${esc(s.area)} · ${s.distance.toFixed(1)} km</div></div><span class="app-badge">${availableCount(s)} ${t('available')}</span></div><div class="app-row" style="margin-top:10px"><b>${money(s.rate)} / kWh</b><button class="app-button" onclick="navigateToStation('${s.id}')">↗ ${t('directions')}</button></div></div>`}
function renderScan(){shell(`<div class="app-card scan-panel"><div class="app-small">${t('guestMode')}</div><h1>${t('scanTitle')}</h1><p class="scanner-hint">No sign-in or camera permission is needed in this demo. Align the QR code inside the frame or enter the charger ID below.</p><div class="scanner-frame" aria-label="Animated QR scan frame"><div class="scanner-grid"></div><i class="scanner-beam"></i><i class="scanner-corner tl"></i><i class="scanner-corner tr"></i><i class="scanner-corner bl"></i><i class="scanner-corner br"></i><span class="app-badge" style="position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);background:#ffffff18;color:#f1f5ee">▦ QR</span></div><button class="app-button full" onclick="simulateGuestScan()">${t('simulateScan')}</button><details class="manual-entry"><summary>Can’t scan? Enter charger code</summary><p class="app-muted">Use the code printed on the charger label.</p><input class="app-input" id="guestCodeInput" value="${esc(appState.guestCode)}" autocomplete="off" autocapitalize="characters" placeholder="AFE-OX-01"><button class="app-button secondary full" style="margin-top:9px" onclick="simulateGuestScan()">${t('continue')}</button></details><div class="app-notice">${t('demoOnly')}</div></div>`)}
function startConnectionAnimation(){if(appState.tick)clearInterval(appState.tick);if(appState.connectTimer)clearInterval(appState.connectTimer);appState.connectStep=0;appState.page='connecting';render();appState.connectTimer=setInterval(()=>{appState.connectStep++;if(appState.connectStep>=3){clearInterval(appState.connectTimer);appState.page='live';render();appState.tick=setInterval(tickSession,1500)}else renderConnecting()},900)}
function renderConnecting(){const steps=['Establishing OCPP connection','Sending start instruction to charger','Confirming charger response'];shell(`<section class="connection-screen"><div class="connection-orb"><div class="connection-spinner"></div></div><div class="app-small">AFE CHARGE · DEMO</div><h1>${t('connecting')}</h1><p class="app-muted">${esc(station().name)} · ${esc(connector().label)}</p><div class="connection-steps">${steps.map((step,i)=>`<div class="connection-step ${i===appState.connectStep?'active':i<appState.connectStep?'done':''}"><span class="connection-step-icon">${i<appState.connectStep?'✓':i===appState.connectStep?'↻':i+1}</span><span>${step}</span></div>`).join('')}</div><p class="app-muted">Secure demo handshake · no charger is contacted</p></section>`)}
function beginGuestConnection(){const s=station(),c=connector();appState.active={id:`AFE-G-${Date.now().toString().slice(-7)}`,stationId:s.id,connectorId:c.id,mode:'amount',limit:Number(appState.guestLimit),cap:Number(appState.guestLimit),energy:0,cost:0,started:Date.now(),customerType:'personal',payment:'card',preauth:Number(appState.guestLimit),guest:true};pushNotice('Guest session starting',s.name,`${c.label} · ${money(appState.guestLimit)} pre-authorisation`,appState.active.id);startConnectionAnimation()}
function renderGuestConnecting(){renderConnecting()}
function startSession(){const s=station(),c=connector(),v=Number(appState.limit);if(!v||v<1){toast('Enter a valid charge limit');return}if(!isStartable(s)||c.status!=='Available'){toast('This station is not startable in the current demo scenario');return}if(appState.customerType==='personal'&&appState.failure!=='none'){appState.page='failure';render();return}const cap=appState.mode==='amount'?v:appState.mode==='energy'?v*s.rate:Math.max(20,(v-35)*.9*s.rate),fleet=appState.customerType==='fleet';appState.active={id:`AFE-${Date.now().toString().slice(-7)}`,stationId:s.id,connectorId:c.id,mode:appState.mode,limit:v,cap,energy:0,cost:0,started:Date.now(),customerType:appState.customerType,payment:fleet?'fleet':appState.payment,preauth:!fleet&&appState.payment==='card'?cap:0,fleetVehicleId:fleet?DEMO_DATA.fleet.vehicleId:null,fleetPlate:fleet?DEMO_DATA.fleet.plate:null};pushNotice('Charging started',`${s.name} · ${c.label}`,`${money(0)} · 0.0 kWh`,appState.active.id);startConnectionAnimation()}
function clearDemoData(){if(!confirm('Clear demo sessions, notifications, wallet and preferences on this device?'))return;try{localStorage.removeItem(STORE_KEY)}catch(error){console.warn('AFE Charge: local storage unavailable',error)}store=loadStore();appState.page='find';routeStack.splice(0,routeStack.length,'find');render();toast('Demo data cleared')}
function render(){if(appState.page==='find')return renderHome();if(appState.page==='station')return renderStation();if(appState.page==='setup')return renderSetup();if(appState.page==='failure')return renderFailure();if(appState.page==='connecting'||appState.page==='guestConnecting')return renderConnecting();if(appState.page==='live')return renderLive();if(appState.page==='summary')return renderSummary();if(appState.page==='history')return renderHistory();if(appState.page==='invoice')return renderInvoice();if(appState.page==='notifications')return renderNotifications();if(appState.page==='profile')return renderProfile();if(appState.page==='payments')return renderPayments();if(appState.page==='fleet')return renderFleetStatement();if(appState.page==='scan')return renderScan();if(appState.page==='guest')return renderGuest();if(appState.page==='wallet')return renderWallet();if(appState.page==='settings')return renderSettings();if(appState.page==='emergency')return renderEmergency();if(appState.page==='feedback')return renderFeedback();if(appState.page==='help')return renderHelp();if(appState.page==='cardForm')return renderCardForm();renderHome()}
function toast(msg){const root=document.getElementById('toastRoot');if(!root)return;root.innerHTML=`<div class="app-toast">${esc(translateMarkup(String(msg)))}</div>`;clearTimeout(appState.toastTimer);appState.toastTimer=setTimeout(()=>{if(root)root.innerHTML=''},2400)}
function initApp(){render();window.addEventListener('popstate',()=>{if(appState.page==='connecting'){clearTimeout(appState.connectTimer);appState.active=null}if(routeStack.length>1)routeStack.pop();appState.page=routeStack.at(-1)||'find';appState.transitionDirection='back';render()});window.addEventListener('online',render);window.addEventListener('offline',render)}



function translateText(text){const dict=COPY_TABLE[store.language]||{};let out=String(text);for(const [en,value] of Object.entries(dict).sort((a,b)=>b[0].length-a[0].length)){const escaped=en.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');out=out.replace(new RegExp('(?<![A-Za-z0-9_])'+escaped+'(?![A-Za-z0-9_])','gi'),value)}return out}
function translateMarkup(html){if(store.language==='en')return String(html);const tpl=document.createElement('template');tpl.innerHTML=String(html);const walker=document.createTreeWalker(tpl.content,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);for(const node of nodes)node.textContent=translateText(node.textContent);tpl.content.querySelectorAll('[placeholder],[aria-label],[title]').forEach(el=>['placeholder','aria-label','title'].forEach(attr=>{if(el.hasAttribute(attr))el.setAttribute(attr,translateText(el.getAttribute(attr)))}));return tpl.innerHTML}
function toast(msg){const root=document.getElementById('toastRoot');if(!root)return;root.innerHTML=`<div class="app-toast">${esc(translateText(msg))}</div>`;clearTimeout(appState.toastTimer);appState.toastTimer=setTimeout(()=>{if(root)root.innerHTML=''},2400)}

// Map-first consumer shell and lightweight native-style route transitions.
function appHeader(){const unread=store.notifications.filter(n=>!n.read).length;return `<header class="app-header"><div class="app-brand"><span class="app-brandmark">ϟ</span><span>AFE Charge</span><span class="demo-chip demo-muted" aria-label="${t('demoOnly')}">DEMO</span></div><div class="app-inline"><button class="app-button ghost mode-toggle" onclick="toggleOpsMode()">${store.cpoMode?'Driver view':'CPO view'}</button><button class="app-button ghost header-notifications" aria-label="${t('notifications')}" onclick="showPage('notifications')">♧${unread?` <sup>${unread}</sup>`:''}</button></div></header>${!navigator.onLine?`<div class="offline-ribbon">${t('offlineDemo')}</div>`:''}`}
function renderHome(){
  if(!store.cpoMode)store.homeView='map';
  const list=filteredStations(),rec=recommendation(),ops=store.cpoMode;
  const stationRows=list.map(s=>`<button class="drawer-station" onclick="openStation('${s.id}')"><span class="drawer-station-icon ${s.id===rec?.id?'is-featured':''}">${availableCount(s)}</span><span class="drawer-station-copy"><b>${esc(s.name)}</b><small>${esc(s.area)} · ${s.distance.toFixed(1)} km · ${money(s.rate)}/kWh</small><small>${availableCount(s)} ${t('available')} · ${s.successRate}% ${t('successRate')}</small></span><span class="drawer-chevron">›</span></button>`).join('');
  const card=rec?`<button class="recommended-card" onclick="openStation('${rec.id}')"><span class="recommended-avatar">ϟ</span><span class="recommended-copy"><small>${t('recommendedStation')}</small><b>${esc(rec.name)}</b><span>${rec.distance.toFixed(1)} km · ${availableCount(rec)} ${t('available')} · ${money(rec.rate)}/kWh</span><span class="recommended-proof">${rec.successRate}% ${t('successRate')} · ${esc(rec.lastSuccess)}</span></span><span class="recommended-arrow">›</span></button>`:`<div class="recommended-card is-empty"><b>${t('noStationsForFilters')}</b></div>`;
  const economics=ops&&rec?`<div class="drawer-economy">${economyMarkup(rec,true)}</div>`:'';
  const content=`<section class="home-map-first ${ops?'operator-map':''}"><div class="map-home-top"><div><span class="map-eyebrow">${ops?t('cpoView'):t('chargingStations')}</span><h1>${ops?t('stationEconomics'):t('findCharger')}</h1></div><button class="map-filter-button" onclick="${ops?'toggleLoadShedding()':'openFilters()'}" aria-label="${t('filter')}">${ops?'◉':'☷'}</button></div><div class="app-map-wrap">${renderMapView()}<div id="mapSheetRoot" class="marker-sheet-root"></div><section id="stationDrawer" class="station-drawer collapsed" aria-label="${t('nearbyStations')}"><button class="drawer-grabber" aria-label="${t('expandStations')}" onclick="toggleStationDrawer()"><i></i></button><div class="drawer-heading"><div><b>${ops?t('stationEconomics'):t('nearbyStations')}</b><span>${list.length} ${t('stationsCount')}</span></div><button class="drawer-expand" onclick="toggleStationDrawer()" aria-label="${t('expandStations')}">⌃</button></div>${card}${economics}<div class="drawer-stations">${stationRows}</div><div class="drawer-footnote">${t('demoOnly')}</div></section></div></section>`;
  shell(content);
  const main=document.querySelector('.app-main');main?.classList.add('home-main');
  bindStationDrawerGesture();
  if(window.AFE_CONFIG?.GOOGLE_MAPS_API_KEY){if(appState.mapsState==='idle')loadGoogleMaps();if(appState.mapsState==='ready')drawGoogleMap()}
}
function toggleStationDrawer(force){const drawer=document.getElementById('stationDrawer');if(!drawer)return;const expand=typeof force==='boolean'?force:!drawer.classList.contains('expanded');drawer.classList.toggle('expanded',expand);drawer.classList.toggle('collapsed',!expand)}
function bindStationDrawerGesture(){const drawer=document.getElementById('stationDrawer');if(!drawer||drawer.dataset.gestureBound)return;drawer.dataset.gestureBound='1';let startY=0;drawer.addEventListener('pointerdown',e=>{if(e.target.closest('button:not(.drawer-grabber)'))return;startY=e.clientY});drawer.addEventListener('pointerup',e=>{if(!startY)return;const delta=startY-e.clientY;startY=0;if(Math.abs(delta)>35)toggleStationDrawer(delta>0)})}
function renderMapView(){const selected=appState.selectedMarker?station(appState.selectedMarker):null;const points=[['afe-rivonia',50,46],['oxford',25,53],['rosebank',54,34],['sandton',76,67]];const markers=points.filter(([id])=>id==='afe-rivonia'||(!appState.filter.recent||isStartable(station(id)))).map(([id,left,top])=>{const st=station(id),featured=st.id==='afe-rivonia';return `<button class="afe-map-marker ${featured?'featured afe-featured-site':''} ${st.id===selected?.id?'selected':''}" style="left:${left}%;top:${top}%" aria-label="${esc(st.name)} · ${availableCount(st)} ${t('available')}" onclick="showMapStation('${id}')">${featured?`<span class="marker-bolt">ϟ</span><small>${availableCount(st)}</small>`:`<span>${availableCount(st)}</span>`}</button>`}).join('');const live=appState.mapsState==='ready'&&window.google?.maps;const background=live?'':`<div class="afe-map-fallback premium-map" aria-label="${t('illustratedMap')}"><div class="map-neighborhood n1">EDENBURG</div><div class="map-neighborhood n2">SANDTON</div><div class="map-waterway"></div><div class="map-road road-a"></div><div class="map-road road-b"></div><div class="map-road road-c"></div><div class="map-park park-a"></div><div class="map-park park-b"></div>${markers}<div class="map-scale">${appState.mapsState==='error'?t('mapUnavailable'):t('mapPreview')}</div></div>`;return `<div class="app-map-canvas" id="afeMap">${background}</div><div class="map-controls"><button onclick="toast('${t('mapPreview')}')" aria-label="${t('myLocation')}">◎</button><span>${live?'Google Maps · Sandton':t('mapPreview')}</span></div>`}
function addGoogleMarkers(AdvancedMarkerElement){if(!appState.mapsInstance)return;const featured=recommendation();DEMO_DATA.stations.filter(s=>!appState.filter.recent||isStartable(s)).forEach(s=>{const markerContent=document.createElement('button');markerContent.type='button';markerContent.className=`afe-map-marker ${s.id===featured?.id?'featured':''}`;markerContent.innerHTML=`<span>${availableCount(s)}</span>`;markerContent.setAttribute('aria-label',`${s.name}: ${availableCount(s)} ${t('available')||'available'}`);const marker=new AdvancedMarkerElement({map:appState.mapsInstance,position:{lat:s.lat,lng:s.lng},title:s.name,content:markerContent,gmpClickable:true});marker.addListener('gmp-click',()=>showMapStation(s.id));appState.mapMarkers.push(marker)})}
function showMapStation(id){appState.selectedMarker=id;document.querySelectorAll('.afe-map-marker').forEach(el=>el.classList.toggle('selected',el.getAttribute('aria-label')?.includes(station(id).name)));const root=document.getElementById('mapSheetRoot');if(root){root.innerHTML=translateMarkup(mapStationSheet(station(id)));root.classList.add('is-visible')}const recCard=document.querySelector('.recommended-card');if(recCard)recCard.classList.toggle('marker-selected',id===recommendation()?.id)}
function shell(content){applyPreferences();const mount=document.querySelector('.appview');if(!mount)return;const wrapper=document.createElement('div');wrapper.className='app-root';wrapper.dataset.fontSize=store.fontSize;const direction=appState.transitionDirection||'none';appState.transitionDirection=null;wrapper.innerHTML=translateMarkup(appHeader())+`<main class="app-main ${direction==='back'?'page-enter-left':'page-enter-right'}">${translateMarkup(content)}</main>${nav()}<div id="overlayRoot"></div><div id="toastRoot"></div>`;mount.replaceChildren(wrapper)}
function showPage(page){if(page===appState.page)return;const priorIndex=routeStack.lastIndexOf(page);if(priorIndex>=0&&priorIndex<routeStack.length-1){routeStack.splice(priorIndex+1);appState.transitionDirection='back'}else{routeStack.push(page);appState.transitionDirection='forward';try{history.pushState({afePage:page},'',`#${page}`)}catch{}}appState.page=page;render()}
function openStation(id){appState.stationId=id||appState.stationId;showPage('station')}
function selectConnector(sid,cid){appState.stationId=sid;appState.connectorId=cid;showPage('setup')}
function startConnectionAnimation(){if(appState.tick)clearInterval(appState.tick);if(appState.connectTimer)clearTimeout(appState.connectTimer);appState.liveReadouts=null;appState.connectStep=0;appState.page='connecting';renderConnecting();const advance=()=>{if(appState.page!=='connecting')return;if(appState.connectStep<2){appState.connectStep++;renderConnecting();appState.connectTimer=setTimeout(advance,920);return}appState.connectTimer=setTimeout(()=>{if(appState.page!=='connecting')return;appState.page='live';renderLive();appState.tick=setInterval(tickSession,1500)},760)};appState.connectTimer=setTimeout(advance,920)}
function renderConnecting(){const steps=['connectingSecure','sendingStart','startSuccess'];shell(`<section class="connection-screen"><div class="connection-orb"><div class="connection-spinner ${appState.connectStep===2?'success-orb':''}">${appState.connectStep===2?'✓':''}</div></div><div class="app-small">AFE CHARGE · ${t('demoBadge')}</div><h1>${t('connecting')}</h1><p class="app-muted">${esc(station().name)} · ${esc(connector().label)}</p><div class="connection-steps">${steps.map((key,i)=>`<div class="connection-step ${i===appState.connectStep?'active':''} ${i<appState.connectStep?'done':''}"><span class="connection-step-icon">${i<appState.connectStep?'✓':i===appState.connectStep?(i===2?'✓':'↻'):i+1}</span><span>${t(key)}</span></div>`).join('')}</div><p class="connection-boundary">${t('noRealConnection')}</p></section>`)}
function renderLive(){if(!appState.active)return;const a=appState.active,s=station(a.stationId),remaining=Math.max(0,a.cap-a.cost),pct=Math.min(100,a.cost/a.cap*100),previous=appState.liveReadouts||{energy:a.energy,cost:a.cost,remaining,battery:42+Math.floor(a.energy)},current={energy:a.energy,cost:a.cost,remaining,battery:Math.min(95,42+Math.floor(a.energy))};shell(`<section class="live-page"><div class="live-topline"><span class="live-status-dot"></span><span>${t('chargingNow')}</span><span class="demo-mini">${t('demoBadge')}</span></div><h1>${esc(s.name)}</h1><p class="app-muted">${esc(connector(s,a.connectorId).label)} · ${connector(s,a.connectorId).kw} kW</p><div class="live-energy-card"><span class="live-ring"><i style="--progress:${pct}%"></i><b class="live-number" data-counter="energy">${current.energy.toFixed(1)}</b><small>kWh</small></span><div class="live-amount-caption">${t('currentDemoCost')}</div><strong class="live-cost live-number" data-counter="cost">${money(current.cost)}</strong><div class="live-progress"><i style="width:${pct}%"></i></div></div><div class="live-metrics"><div><span>${t('used')}</span><b class="live-number" data-counter="cost">${money(current.cost)}</b></div><div><span>${t('remainingLimit')}</span><b class="live-number" data-counter="remaining">${money(current.remaining)}</b></div><div><span>${t('battery')}</span><b class="live-number" data-counter="battery">${current.battery}%</b></div></div><div class="live-limit-card"><div class="app-row"><div><span class="app-small">${t('chargeLimit')}</span><b>${money(a.cap)}</b></div><span class="live-session-time">${formatDuration(Date.now()-a.started)}</span></div><button class="app-button secondary full" onclick="adjustLiveLimit()">${t('adjustLimit')}</button><button class="app-button ghost full" onclick="advanceDemo()">${t('advanceDemo')}</button></div><button class="app-button danger full live-stop" onclick="finishSession('Stopped by driver')">${t('stop')}</button><p class="live-boundary">${t('noRealConnection')}</p></section>`);appState.liveReadouts=current;animateLiveReadouts(previous,current)}
function animateLiveReadouts(from,to){const nodes=document.querySelectorAll('[data-counter]');if(!nodes.length)return;const started=performance.now(),duration=520,ease=p=>1-Math.pow(1-p,3);const frame=now=>{const p=Math.min(1,(now-started)/duration),q=ease(p);nodes.forEach(node=>{const key=node.dataset.counter,value=from[key]+(to[key]-from[key])*q;node.textContent=key==='energy'?value.toFixed(1):key==='battery'?`${Math.round(value)}%`:money(value)});if(p<1)requestAnimationFrame(frame)};requestAnimationFrame(frame)}
function formatDuration(ms){const sec=Math.max(0,Math.floor(ms/1000)),min=Math.floor(sec/60);return `${String(Math.floor(min/60)).padStart(2,'0')}:${String(min%60).padStart(2,'0')}`}
function render(){if(appState.page==='find')return renderHome();if(appState.page==='station')return renderStation();if(appState.page==='setup')return renderSetup();if(appState.page==='failure')return renderFailure();if(appState.page==='connecting'||appState.page==='guestConnecting')return renderConnecting();if(appState.page==='live')return renderLive();if(appState.page==='summary')return renderSummary();if(appState.page==='history')return renderHistory();if(appState.page==='invoice')return renderInvoice();if(appState.page==='notifications')return renderNotifications();if(appState.page==='profile')return renderProfile();if(appState.page==='payments')return renderPayments();if(appState.page==='fleet')return renderFleetStatement();if(appState.page==='scan')return renderScan();if(appState.page==='guest')return renderGuest();if(appState.page==='wallet')return renderWallet();if(appState.page==='settings')return renderSettings();if(appState.page==='emergency')return renderEmergency();if(appState.page==='feedback')return renderFeedback();if(appState.page==='help')return renderHelp();if(appState.page==='cardForm')return renderCardForm();renderHome()}



// Mock OCPP status layer. Connector.status remains in sync for older demo screens.
const CONNECTOR_STATES=['Available','Charging','Faulted','Unavailable'];
function normalizeConnectorState(c){if(c.connectorStatus&&CONNECTOR_STATES.includes(c.connectorStatus))return c.connectorStatus;const legacy={'In use':'Charging','Fault':'Faulted','Offline':'Unavailable'};c.connectorStatus=legacy[c.status]|| (CONNECTOR_STATES.includes(c.status)?c.status:'Available');c.stationOnline=typeof c.stationOnline==='boolean'?c.stationOnline:true;c.lastUpdated=c.lastUpdated||new Date().toISOString();return c.connectorStatus}
DEMO_DATA.stations.forEach(s=>s.connectors.forEach(normalizeConnectorState));
function effectiveConnectorStatus(c){return c.stationOnline===false?'Unavailable':normalizeConnectorState(c)}
function statusLabel(status){return t(({Available:'statusAvailable',Charging:'statusCharging',Faulted:'statusFaulted',Unavailable:'statusUnavailable'})[status]||'statusUnavailable')}
function statusClass(status){return({Available:'available',Charging:'charging',Faulted:'faulted',Unavailable:'unavailable'})[status]||'unavailable'}
function stationOnline(s){return s.connectors.some(c=>c.stationOnline!==false)}
function markerState(s){const states=s.connectors.map(effectiveConnectorStatus);if(!stationOnline(s))return'Unavailable';if(states.includes('Available'))return'Available';if(states.length&&states.every(x=>x==='Charging'))return'Charging';if(states.includes('Faulted'))return'Faulted';return'Unavailable'}
function connector(s=station(),id=appState.connectorId){return s.connectors.find(c=>c.id===id)||s.connectors.find(c=>effectiveConnectorStatus(c)==='Available')||s.connectors[0]}
function isStartable(s){return !!s&&stationOnline(s)&&s.connectors.some(c=>effectiveConnectorStatus(c)==='Available')&&!(store.loadShedding&&s.resilience==='Grid only')}
function availableCount(s){return s.connectors.filter(c=>effectiveConnectorStatus(c)==='Available').length&&!(store.loadShedding&&s.resilience==='Grid only')?s.connectors.filter(c=>effectiveConnectorStatus(c)==='Available').length:0}
function filteredStations(){return DEMO_DATA.stations.filter(s=>{if(appState.filter.recent&&!isStartable(s))return false;return s.connectors.some(c=>(!appState.filter.recent||effectiveConnectorStatus(c)==='Available')&&(appState.filter.connector==='Any'||c.type===appState.filter.connector)&&(appState.filter.power==='Any'||c.powerType===appState.filter.power))}).sort((a,b)=>store.cpoMode?(b.economics.utilization/b.economics.breakEven)-(a.economics.utilization/a.economics.breakEven)||a.economics.payback-b.economics.payback:appState.filter.sort?b.successRate-a.successRate:a.distance-b.distance)}
function setConnectorStatus(c,status){if(!CONNECTOR_STATES.includes(status))return;c.connectorStatus=status;c.status=({'Charging':'In use','Faulted':'Fault','Unavailable':'Unavailable'})[status]||status;c.lastUpdated=new Date().toISOString();refreshStatusUI();refreshStatusCounters()}
function stationStatusMarkup(s){const online=stationOnline(s),onlineLabel=t(online?'stationOnline':'stationOffline');return `<span class="station-online"><i class="station-live-dot ${online?'online':'offline'}"></i>${onlineLabel}</span>`}
function connectorStatusMarkup(c){const status=effectiveConnectorStatus(c);return `<span class="connector-state-chip ${statusClass(status)}" data-connector-status="${esc(c.id)}">${statusLabel(status)}</span>`}
function mapStationSheet(s){return `<div class="app-card map-bottom-sheet"><div class="app-row"><div><h3>${esc(s.name)}</h3><div class="app-muted">${esc(s.area)} · ${s.distance.toFixed(1)} km</div></div><span class="app-badge">${availableCount(s)} ${t('available')}</span></div><div class="app-row" style="margin-top:8px">${stationStatusMarkup(s)}<b>${money(s.rate)} / kWh</b></div><div class="connector-map-summary">${s.connectors.map(c=>`<span class="connector-state-chip ${statusClass(effectiveConnectorStatus(c))}">${esc(c.label)} · ${statusLabel(effectiveConnectorStatus(c))}</span>`).join('')}</div><div class="app-row" style="margin-top:10px"><span class="app-small">${t('lastUpdated')}: ${new Date(Math.max(...s.connectors.map(c=>new Date(c.lastUpdated).getTime()||0))).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit',second:'2-digit'})}</span><button class="app-button" onclick="navigateToStation('${s.id}')">↗ ${t('directions')}</button></div></div>`}
function renderStation(){const s=station();shell(`<button class="app-button ghost" onclick="showPage('find')">‹ ${t('backStations')}</button><div class="live-sync-indicator"><i></i>${t('liveStatus')}</div><div class="app-row" style="margin-top:8px"><div><div class="app-small">STATION DETAILS</div><h1>${esc(s.name)}</h1></div><span class="app-badge">${availableCount(s)} ${t('available')}</span></div><div class="app-row station-connectivity">${stationStatusMarkup(s)}<span class="app-small">${t('lastUpdated')}: ${new Date(Math.max(...s.connectors.map(c=>new Date(c.lastUpdated).getTime()||0))).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit',second:'2-digit'})}</span></div><p class="app-muted">${esc(s.address)} · ${esc(s.open)} · ${s.distance.toFixed(1)} km away</p><div class="app-card"><div class="app-row"><h3>Before you arrive</h3><strong>${money(s.rate)} / kWh</strong></div><div class="app-kv"><span>24h successful starts</span><b>${esc(s.lastSuccess)} · ${s.successRate}%</b></div><div class="app-kv"><span>Power access</span><b>${s.connectors.map(c=>c.powerType).filter((x,i,a)=>a.indexOf(x)===i).join(' / ')}</b></div><div class="app-row">${resilienceBadge(s)}<span class="app-small">${store.loadShedding&&s.resilience==='Grid only'?'Unavailable in load-shedding demo':'Load-shedding status: startable'}</span></div><div class="app-alert ${s.cable?'':'green'}">${s.cable?'Cable required for some bays.':'Tethered cable available on CCS bays.'} ${esc(s.parking)}</div><div class="app-row"><button class="app-button secondary" onclick="navigateToStation('${s.id}')">↗ Directions</button><button class="app-button secondary" onclick="chooseFailure()">Demo failure</button></div></div><div class="app-card"><div class="app-row"><h3>Station economics</h3>${resilienceBadge(s)}</div>${economyMarkup(s)}<div class="app-muted">Simulated CPO estimates for partner discussion; not financial guidance.</div></div><h2>Choose a connector</h2>${s.connectors.map(c=>{const status=effectiveConnectorStatus(c),available=status==='Available'&&isStartable(s);return `<div class="app-connector ${available?'':'disabled'} connector-live-card" data-connector-card="${esc(c.id)}"><div class="app-row"><b>${esc(c.label)}</b>${connectorStatusMarkup(c)}</div><div class="app-muted">${esc(c.type)} · ${c.powerType} · ${c.kw} kW · ${c.cable?'Bring cable':'Cable supplied'}</div><div class="app-small connector-updated" data-connector-time="${esc(c.id)}">${t('lastUpdated')}: ${new Date(c.lastUpdated).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit',second:'2-digit'})}</div><button class="app-button full ${available?'':'secondary'}" style="margin-top:9px" ${available?'':'disabled'} onclick="selectConnector('${s.id}','${c.id}')">${available?'Select this gun':t('connectorUnavailable')}</button></div>`}).join('')}<div class="app-alert">Open parking areas can have cable theft risk. Keep the cable attended while charging.</div><button class="app-button secondary full" onclick="showPage('setup')">Try a startup failure scenario</button>`)}
function selectConnector(sid,cid){const s=station(sid),c=s.connectors.find(x=>x.id===cid);if(!c||effectiveConnectorStatus(c)!=='Available'||!isStartable(s)){toast(t('connectorUnavailable'));return}appState.stationId=sid;appState.connectorId=cid;showPage('setup')}
function startSession(){const s=station(),c=connector(s),v=Number(appState.limit);if(!v||v<1){toast('Enter a valid charge limit');return}if(!stationOnline(s)||effectiveConnectorStatus(c)!=='Available'||!isStartable(s)){toast(t('connectorUnavailable'));return}if(appState.customerType==='personal'&&appState.failure!=='none'){appState.page='failure';render();return}const cap=appState.mode==='amount'?v:appState.mode==='energy'?v*s.rate:Math.max(20,(v-35)*.9*s.rate),fleet=appState.customerType==='fleet';appState.active={id:`AFE-${Date.now().toString().slice(-7)}`,stationId:s.id,connectorId:c.id,mode:appState.mode,limit:v,cap,energy:0,cost:0,started:Date.now(),customerType:appState.customerType,payment:fleet?'fleet':appState.payment,preauth:!fleet&&appState.payment==='card'?cap:0,fleetVehicleId:fleet?DEMO_DATA.fleet.vehicleId:null,fleetPlate:fleet?DEMO_DATA.fleet.plate:null};setConnectorStatus(c,'Charging');pushNotice('Charging started',`${s.name} · ${c.label}`,`${money(0)} · 0.0 kWh`,appState.active.id);startConnectionAnimation()}
function beginGuestConnection(){const s=station(),c=connector(s);if(!isStartable(s)||effectiveConnectorStatus(c)!=='Available'){toast(t('connectorUnavailable'));return}appState.active={id:`AFE-G-${Date.now().toString().slice(-7)}`,stationId:s.id,connectorId:c.id,mode:'amount',limit:Number(appState.guestLimit),cap:Number(appState.guestLimit),energy:0,cost:0,started:Date.now(),customerType:'personal',payment:'card',preauth:Number(appState.guestLimit),guest:true};setConnectorStatus(c,'Charging');pushNotice('Guest session starting',s.name,`${c.label} · ${money(appState.guestLimit)} pre-authorisation`,appState.active.id);startConnectionAnimation()}
const finishSessionBase=finishSession;finishSession=function(reason){const active=appState.active;if(active){const s=station(active.stationId),c=s.connectors.find(x=>x.id===active.connectorId);if(c)setConnectorStatus(c,'Available')}return finishSessionBase(reason)};
function renderMapView(){const selected=appState.selectedMarker?station(appState.selectedMarker):null;const points=[['afe-rivonia',50,46],['oxford',25,53],['rosebank',54,34],['sandton',76,67]];const markers=points.filter(([id])=>id==='afe-rivonia'||(!appState.filter.recent||isStartable(station(id)))).map(([id,left,top])=>{const s=station(id),featured=s.id==='afe-rivonia',state=markerState(s);return `<button data-station-marker="${id}" class="afe-map-marker ${featured?'featured afe-featured-site':''} marker-${statusClass(state)} ${s.id===selected?.id?'selected':''}" style="left:${left}%;top:${top}%" aria-label="${esc(s.name)} · ${availableCount(s)} ${t('available')} · ${statusLabel(state)}" onclick="showMapStation('${id}')">${featured?`<span class="marker-bolt">ϟ</span><small>${availableCount(s)}</small>`:`<span>${availableCount(s)}</span>`}</button>`}).join('');const live=appState.mapsState==='ready'&&window.google?.maps;const background=live?'':`<div class="afe-map-fallback premium-map" aria-label="${t('illustratedMap')}"><div class="map-neighborhood n1">EDENBURG</div><div class="map-neighborhood n2">SANDTON</div><div class="map-waterway"></div><div class="map-road road-a"></div><div class="map-road road-b"></div><div class="map-road road-c"></div><div class="map-park park-a"></div><div class="map-park park-b"></div>${markers}<div class="map-scale">${appState.mapsState==='error'?t('mapUnavailable'):t('mapPreview')}</div></div>`;return `<div class="app-map-canvas" id="afeMap">${background}</div><div class="map-controls"><button onclick="toast('${t('mapPreview')}')" aria-label="${t('myLocation')}">◎</button><span>${live?'Google Maps · Sandton':t('mapPreview')}</span></div>`}
function addGoogleMarkers(AdvancedMarkerElement){if(!appState.mapsInstance)return;const featured=recommendation();DEMO_DATA.stations.filter(s=>!appState.filter.recent||isStartable(s)).forEach(s=>{const content=document.createElement('button');content.type='button';content.dataset.stationMarker=s.id;content.className=`afe-map-marker marker-${statusClass(markerState(s))} ${s.id===featured?.id?'featured':''} ${s.id==='afe-rivonia'?'afe-featured-site':''}`;content.innerHTML=s.id==='afe-rivonia'?`<span class="marker-bolt">ϟ</span><small>${availableCount(s)}</small>`:`<span>${availableCount(s)}</span>`;content.setAttribute('aria-label',`${s.name}: ${availableCount(s)} ${t('available')} · ${statusLabel(markerState(s))}`);const marker=new AdvancedMarkerElement({map:appState.mapsInstance,position:{lat:s.lat,lng:s.lng},title:s.name,content,gmpClickable:true});marker.addListener('gmp-click',()=>showMapStation(s.id));appState.mapMarkers.push({stationId:s.id,marker,content})})}
function drawGoogleMap(){const el=document.getElementById('afeMap');if(!el||appState.mapsState!=='ready'||!window.google?.maps)return;try{appState.mapMarkers.forEach(entry=>(entry.marker||entry).map=null);appState.mapMarkers=[];appState.mapsInstance=new google.maps.Map(el,{center:{lat:-26.043889,lng:28.060290},zoom:15,mapId:window.AFE_CONFIG?.GOOGLE_MAP_ID||'DEMO_MAP_ID',mapTypeControl:false,streetViewControl:false,fullscreenControl:false});const AdvancedMarkerElement=google.maps.marker?.AdvancedMarkerElement;if(AdvancedMarkerElement)addGoogleMarkers(AdvancedMarkerElement);else google.maps.importLibrary('marker').then(({AdvancedMarkerElement})=>addGoogleMarkers(AdvancedMarkerElement)).catch(failGoogleMaps)}catch{failGoogleMaps()}}
function refreshStatusUI(){DEMO_DATA.stations.forEach(s=>{const state=markerState(s),online=stationOnline(s);document.querySelectorAll(`[data-station-marker="${s.id}"]`).forEach(el=>{el.classList.remove('marker-available','marker-charging','marker-faulted','marker-unavailable');el.classList.add(`marker-${statusClass(state)}`);const countEl=el.querySelector('small,span:not(.marker-bolt)');if(countEl)countEl.textContent=String(availableCount(s));el.setAttribute('aria-label',`${s.name} · ${availableCount(s)} ${t('available')} · ${statusLabel(state)}`)});document.querySelectorAll(`.drawer-station[onclick*="${s.id}"],.recommended-card[onclick*="${s.id}"]`).forEach(row=>{let summary=row.querySelector('.connector-live-summary');if(!summary){summary=document.createElement('small');summary.className='connector-live-summary';row.querySelector('.drawer-station-copy,.recommended-copy')?.append(summary)}summary.textContent=`${s.connectors.filter(c=>effectiveConnectorStatus(c)==='Available').length} ${statusLabel('Available')} · ${s.connectors.filter(c=>effectiveConnectorStatus(c)==='Charging').length} ${statusLabel('Charging')}`;let dot=row.querySelector('.station-live-dot');if(!dot){dot=document.createElement('i');dot.className='station-live-dot';row.querySelector('.drawer-station-icon,.recommended-avatar')?.append(dot)}dot.classList.toggle('online',online);dot.classList.toggle('offline',!online)});s.connectors.forEach(c=>{const st=effectiveConnectorStatus(c),chip=document.querySelector(`[data-connector-status="${c.id}"]`);if(chip){chip.className=`connector-state-chip ${statusClass(st)} status-updated`;chip.textContent=statusLabel(st);setTimeout(()=>chip.classList.remove('status-updated'),650)}const time=document.querySelector(`[data-connector-time="${c.id}"]`);if(time)time.textContent=`${t('lastUpdated')}: ${new Date(c.lastUpdated).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit',second:'2-digit'})}`;const card=document.querySelector(`[data-connector-card="${c.id}"]`);if(card){const button=card.querySelector('button'),available=st==='Available'&&isStartable(s);card.classList.toggle('disabled',!available);if(button){button.disabled=!available;button.className=`app-button full ${available?'':'secondary'}`;button.textContent=available?'Select this gun':t('connectorUnavailable')}}});const badge=document.querySelector('.live-sync-indicator');if(badge)badge.setAttribute('aria-label',`${t('liveStatus')} · ${online?t('stationOnline'):t('stationOffline')}`)});document.querySelectorAll('.afe-map-marker').forEach(el=>{el.style.transition='background-color .35s, transform .25s, box-shadow .35s'})}
function refreshStatusCounters(){DEMO_DATA.stations.forEach(s=>{const tally=Object.fromEntries(CONNECTOR_STATES.map(state=>[state,s.connectors.filter(c=>effectiveConnectorStatus(c)===state).length]));const summaryText=`${tally.Available} ${statusLabel('Available')} · ${tally.Charging} ${statusLabel('Charging')} · ${tally.Faulted} ${statusLabel('Faulted')} · ${tally.Unavailable} ${statusLabel('Unavailable')}`;document.querySelectorAll(`.drawer-station[onclick*="${s.id}"]`).forEach(row=>{const icon=row.querySelector('.drawer-station-icon');if(icon?.firstChild?.nodeType===Node.TEXT_NODE)icon.firstChild.nodeValue=String(availableCount(s));const summary=row.querySelector('.connector-live-summary');if(summary)summary.textContent=summaryText});document.querySelectorAll(`.recommended-card[onclick*="${s.id}"]`).forEach(row=>{const primary=row.querySelector('.recommended-copy span:not(.recommended-proof)');if(primary)primary.textContent=`${s.distance.toFixed(1)} km · ${availableCount(s)} ${t('available')} · ${money(s.rate)}/kWh`;const summary=row.querySelector('.connector-live-summary');if(summary)summary.textContent=summaryText});if(appState.page==='station'&&appState.stationId===s.id){const count=document.querySelector('.app-main h1')?.closest('.app-row')?.querySelector('.app-badge');if(count)count.textContent=`${availableCount(s)} ${t('available')}`;const dot=document.querySelector('.station-connectivity .station-live-dot'),label=document.querySelector('.station-connectivity .station-online');if(dot){dot.classList.toggle('online',stationOnline(s));dot.classList.toggle('offline',!stationOnline(s))}if(label)label.lastChild.textContent=`${stationOnline(s)?t('stationOnline'):t('stationOffline')}`};const chip=document.querySelector('.live-sync-indicator');if(chip)chip.innerHTML=`<i></i>${t('liveStatus')}`;const sheet=document.querySelector('.marker-sheet-root.is-visible');if(sheet&&appState.selectedMarker===s.id)sheet.innerHTML=mapStationSheet(s)})}
function startMockStatusFeed(){if(appState.statusFeed)return;appState.statusFeed=setInterval(()=>{let candidates=station('afe-rivonia').connectors.filter(c=>c.stationOnline!==false&&(!appState.active||c.id!==appState.active.connectorId));if(!candidates.length)candidates=DEMO_DATA.stations.flatMap(s=>s.connectors.filter(c=>c.stationOnline!==false&&(!appState.active||c.id!==appState.active.connectorId)));const c=candidates[Math.floor(Math.random()*candidates.length)];if(!c)return;const old=effectiveConnectorStatus(c);if(old==='Available')setConnectorStatus(c,'Charging');else if(old==='Charging')setConnectorStatus(c,'Available');else setConnectorStatus(c,'Available');if(appState.page==='find'&&store.homeView==='map'&&appState.mapsState==='ready')refreshGoogleMarker(c)} ,7000);setTimeout(refreshStatusUI,0)}
function refreshGoogleMarker(c){const s=DEMO_DATA.stations.find(x=>x.connectors.includes(c));if(!s)return;const entry=appState.mapMarkers.find(x=>x.stationId===s.id);if(entry){const state=markerState(s);entry.content.classList.remove('marker-available','marker-charging','marker-faulted','marker-unavailable');entry.content.classList.add(`marker-${statusClass(state)}`);entry.content.querySelector('small,span:not(.marker-bolt)')?.replaceChildren(document.createTextNode(String(availableCount(s))));entry.content.setAttribute('aria-label',`${s.name}: ${availableCount(s)} ${t('available')} · ${statusLabel(state)}`)}}
function installLiveStatusIndicator(){if(appState.page==='find'){const top=document.querySelector('.map-home-top');if(top&&!top.querySelector('.live-sync-indicator')){const badge=document.createElement('div');badge.className='live-sync-indicator';badge.innerHTML=`<i></i>${t('liveStatus')}`;top.append(badge)}const controls=document.querySelector('.map-controls');if(controls&&!document.querySelector('.connector-map-legend')){const legend=document.createElement('div');legend.className='connector-map-legend';legend.innerHTML=CONNECTOR_STATES.map(state=>`<span><i class="legend-dot ${statusClass(state)}"></i>${statusLabel(state)}</span>`).join('');controls.insertAdjacentElement('afterend',legend)}}refreshStatusUI()}
