function setScanStatus(message){const status=document.getElementById('scanCameraStatus');if(status)status.textContent=message}
function loadQrDecoder(){if(window.jsQR)return Promise.resolve(true);if(appState.qrDecoderPromise)return appState.qrDecoderPromise;appState.qrDecoderPromise=new Promise(resolve=>{const script=document.createElement('script');script.src='https://cdn.jsdelivr.net/npm/jsqr@1.4.0/dist/jsQR.min.js';script.async=true;script.onload=()=>resolve(!!window.jsQR);script.onerror=()=>resolve(false);document.head.appendChild(script)});return appState.qrDecoderPromise}
async function startCameraScan(){if(appState.cameraStream)return;if(!window.isSecureContext||!navigator.mediaDevices?.getUserMedia){setScanStatus(t('cameraUnavailable'));toast(t('cameraUnavailable'));return}setScanStatus(t('cameraStarting'));const button=document.getElementById('cameraStartButton');if(button)button.disabled=true;try{const stream=await navigator.mediaDevices.getUserMedia({audio:false,video:{facingMode:{ideal:'environment'},width:{ideal:1280},height:{ideal:720}}});appState.cameraStream=stream;const video=document.getElementById('scanVideo');if(!video){stopCameraScan();return}video.srcObject=stream;video.hidden=false;await video.play();document.getElementById('scanCamera')?.classList.add('has-video');const stop=document.getElementById('cameraStopButton');if(stop)stop.style.display='block';if(button)button.textContent=`✓ ${t('cameraReady')}`;if('BarcodeDetector'in window){try{appState.qrDetector=new window.BarcodeDetector({formats:['qr_code']})}catch{appState.qrDetector=null}}if(!appState.qrDetector&&!await loadQrDecoder()){setScanStatus(t('cameraDecodeFallback'));return}setScanStatus(t('cameraReady'));scanCameraFrame()}catch(error){if(appState.cameraStream)stopCameraScan();else if(button)button.disabled=false;const denied=['NotAllowedError','PermissionDeniedError','SecurityError'].includes(error?.name);setScanStatus(t(denied?'cameraDenied':'cameraUnavailable'));toast(t(denied?'cameraDenied':'cameraUnavailable'))}}
function scanCameraFrame(){if(!appState.cameraStream)return;appState.scanFrameTimer=setTimeout(async()=>{const video=document.getElementById('scanVideo');if(!video||video.readyState<2){scanCameraFrame();return}try{let raw='';if(appState.qrDetector){const codes=await appState.qrDetector.detect(video);raw=codes[0]?.rawValue||''}else if(window.jsQR){const canvas=appState.scanCanvas||(appState.scanCanvas=document.createElement('canvas')),ctx=canvas.getContext('2d',{willReadFrequently:true}),width=Math.min(video.videoWidth||640,960),height=Math.round(width*(video.videoHeight||480)/(video.videoWidth||640));canvas.width=width;canvas.height=height;ctx.drawImage(video,0,0,width,height);raw=window.jsQR(ctx.getImageData(0,0,width,height).data,width,height,{inversionAttempts:'dontInvert'})?.data||''}if(raw){handleScannedChargerCode(raw);return}}catch{}if(appState.cameraStream)scanCameraFrame()},260)}
function stopCameraScan(){clearTimeout(appState.scanFrameTimer);if(appState.cameraStream){appState.cameraStream.getTracks().forEach(track=>track.stop());appState.cameraStream=null}appState.qrDetector=null;const video=document.getElementById('scanVideo');if(video){video.pause();video.srcObject=null;video.hidden=true}document.getElementById('scanCamera')?.classList.remove('has-video');const button=document.getElementById('cameraStartButton');if(button){button.disabled=false;button.textContent=`▣ ${t('cameraAction')}`}const stop=document.getElementById('cameraStopButton');if(stop)stop.style.display='none'}
function normalizeQrValue(value){const raw=String(value||'').trim();try{const url=new URL(raw);for(const key of ['connectorId','chargerId','charger','stationId','id','code']){const found=url.searchParams.get(key);if(found)return found}const segments=url.pathname.split('/').filter(Boolean);if(segments.length)return decodeURIComponent(segments.at(-1))}catch{}return raw}
function handleScannedChargerCode(value){const code=normalizeQrValue(value).trim().toUpperCase();const aliases={'AFE-RV-01':['afe-rivonia','afe-rv-1'],'AFE-RIVONIA-01':['afe-rivonia','afe-rv-1'],'AFE-RV-02':['afe-rivonia','afe-rv-2'],'AFE-RV-03':['afe-rivonia','afe-rv-3'],'AFE-RV-04':['afe-rivonia','afe-rv-4'],'ZA410200010000010001':['afe-rivonia',null]};let match=aliases[code]||null;if(!match){const norm=code.replace(/[^A-Z0-9]/g,'');const found=DEMO_DATA.stations.flatMap(s=>s.connectors.map(c=>({s,c}))).find(({s,c})=>[c.id,`${s.id}-${c.id.split('-').at(-1)}`,c.label].some(v=>String(v).toUpperCase().replace(/[^A-Z0-9]/g,'')===norm));if(found)match=[found.s.id,found.c.id]}if(!match){setScanStatus(t('cameraDecodeFallback'));toast(t('cameraUnknownCode'));return}const s=station(match[0]),c=match[1]?s.connectors.find(x=>x.id===match[1]):s.connectors.find(x=>effectiveConnectorStatus(x)==='Available');if(!c||!isStartable(s)||effectiveConnectorStatus(c)!=='Available'){toast(t('connectorUnavailable'));return}stopCameraScan();appState.guestCode=code;appState.stationId=s.id;appState.connectorId=c.id;appState.guestLimit=200;appState.customerType='personal';showPage('guest')}
function simulateGuestScan(){handleScannedChargerCode(document.getElementById('guestCodeInput')?.value||appState.guestCode)}
function setFontSize(size){store.fontSize=['small','large'].includes(size)?size:'medium';saveStore();renderSettingsSection('accessibility')}
function renderRouteV14(){if(appState.page==='personal')return renderPersonalInfo();if(appState.page==='settings-appearance')return renderSettingsSection('appearance');if(appState.page==='settings-language')return renderSettingsSection('language');if(appState.page==='settings-accessibility')return renderSettingsSection('accessibility');if(appState.page==='settings-support')return renderSettingsSection('support');if(appState.page==='settings-about')return renderSettingsSection('about');return null}
const renderBaseV14=render;render=function(){const result=renderRouteV14();if(result!==null)return result;return renderBaseV14()};
const showPageBaseV14=showPage;showPage=function(page){if(page!=='scan')stopCameraScan();return showPageBaseV14(page)};
simulateGuestScan=function(){handleScannedChargerCode(document.getElementById('guestCodeInput')?.value||appState.guestCode)};
window.addEventListener('pagehide',stopCameraScan);window.addEventListener('popstate',()=>{if(appState.page==='scan')stopCameraScan()},{capture:true});
initApp();startMockStatusFeed();

